Object.assign(quranData, {
    10: { // سورة يونس
        name: "يونس",
        basmalaTafsir: ``,
        verses: [
            { text: "الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ", tafsir: `من ألف ولام وراء وغيرها يتركب هذا القرآن المعجز ، فإنه من جنس كلام البشر ، لكنه معجز لا يتمكن أحد أن يأتي بمثله ، كما أن من جنس المعادن والنبات يتركب الإنسان ، لكن لا يقدر أحد على أن يأتي بمثله ، وكذلك جميع صنع الله سبحانه ـ على الاختلاف في أوائل السور ـ ( تِلْكَ آياتُ الْكِتابِ الْحَكِيمِ ) خبر لقوله « الر » أي هذه الحروف آيات الكتاب ـ على بعض الأقوال ـ والمراد ب « الكتاب الحكيم » القرآن العظيم الحاكم بالحق ، المحكم في وصفه وأسلوبه وأحكامه.` },
            { text: "أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ قَالَ ٱلْكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٌ مُّبِينٌ", tafsir: `استفهام إنكاري ، أي : هل إيحاؤنا إلى رجل منهم موجب للعجب والاستغراب ، إنه لا ينبغي ذلك ، فقد أوحي إلى جنس البشر قبل الرسول صلى‌الله‌عليه‌وآله‌وسلم فالأنبياء كلهم كانوا بشرا ( أَنْ أَنْذِرِ النَّاسَ ) مفعول « أوحينا » فقد كان الناس يرتكبون المحرّمات ويفعلون القبائح ، فجاء الرسول صلى‌الله‌عليه‌وآله‌وسلم لينذرهم بالعذاب إن اقترفوا الآثام ( وَبَشِّرِ الَّذِينَ آمَنُوا ) واعتقدوا بما جئت به ( أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِنْدَ رَبِّهِمْ ) فكما أن الإنسان الصادق في قوله لا تزل قدمه عند المحاكمة والحكم ، كذلك من آمن له قدم صدق لا تتزلزل ولا تضطرب عند الله سبحانه ، ويوم محكمته الكبرى ( قالَ الْكافِرُونَ ) الذين لا يعتقدون بالله وآياته : ( إِنَّ هذا ) النبي ـ يعنون محمدا صلى‌الله‌عليه‌وآله‌وسلم ـ ( لَساحِرٌ مُبِينٌ ) أي إِنَّ رَبَّكُمُ اللهُ الَّذِي خَلَقَ السَّماواتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوى عَلَى الْعَرْشِ يُدَبِّرُ الْأَمْرَ ما مِنْ شَفِيعٍ إِلاَّ مِنْ بَعْدِ إِذْنِهِ ذلِكُمُ اللهُ واضح ، حيث أنهم لم يتمكنوا من مقابلته والإتيان بمثل كلامه. [4] ثم عطف سياق الكلام حول الإله ، على الكلام حول الرسول ، وأخّره لأن الرسول صلى‌الله‌عليه‌وآله‌وسلم هو الذي يقول هذا الكلام ويثبته ويدعو إلى التوحيد ويقدم عليه البراهين والأدلة ( إِنَّ رَبَّكُمُ ) أيها البشر ( اللهُ الَّذِي خَلَقَ السَّماواتِ وَالْأَرْضَ ) فالذي خلقهما واخترعهما وأوجدهما من العدم هو ربكم وخالقكم ، لا الأحجار المنحوتة والأشجار وسائر المخلوقات. ( فِي سِتَّةِ أَيَّامٍ ) وقد جرت سنة الله سبحانه على التدرّج في الخلق ، مع أنه قادر على الخلق دفعة واحدة ، فالإنسان والحيوان والنبات كلها تتدرّج في الخلق حتى تكمل ، ولعلّ في ذلك اعتبار للملائكة ونحوهم ، كما أن في تدريج خلقة الإنسان وسائر الأشياء عبرة للبشر ، فإن الإذعان يأتي بالتدريج. وأما خصوصية « الستة » فهي كخصوصية « تسعة أشهر » للجنين وسائر الأزمان المضروبة لسائر المخلوقات. ( ثُمَّ اسْتَوى عَلَى الْعَرْشِ ) أي استولى عليه ، أو توجّه نحو خلقه ـ كما مر في سورة الأعراف ـ ( يُدَبِّرُ الْأَمْرَ ) أي يقدّره وينفذه على وجهه ، فهو الخالق ، وهو الآمر في الكون ( ما مِنْ شَفِيعٍ إِلَّا مِنْ بَعْدِ إِذْنِهِ ) فهو سبحانه كما بدأ وخلق ، وأمر ونفّذ ، كذلك بيده المعاد وإليه المرجع ، وهناك لا بد من الشفاعة للعصاة كما جرت العادة في الدنيا ، ولكن الشفاعة هناك أيضا بيده ، فلا يشفع أحد إلا من بعد إذنه ( ذلِكُمُ اللهُ ) رَبُّكُمْ فَاعْبُدُوهُ أَ فَلا تَذَكَّرُونَ (3) إِلَيْهِ مَرْجِعُكُمْ جَمِيعاً وَعْدَ اللهِ حَقًّا إِنَّهُ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُ لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ بِالْقِسْطِ وَالَّذِينَ كَفَرُوا لَهُمْ شَرابٌ مِنْ حَمِيمٍ وَعَذابٌ أَلِيمٌ بِما كانُوا يَكْفُرُونَ (4) هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِياءً الموصوف بهذه الصفات هو ( رَبَّكُمُ ) لا غيره من الأصنام وسائر المعبودات ( فَاعْبُدُوهُ ) وحده بدون شريك ( أَ فَلا تَذَكَّرُونَ ) فيه حثّ على التذكّر والتفكّر ليهتدوا إلى الطريق ، ويجتنبوا المتاهات. [5] ثم بيّن أن الرجوع إليه كما كان منه البدء ، للتصريح بذلك بعد الإشعار والإلماع إليه ( إِلَيْهِ ) إلى الله سبحانه ( مَرْجِعُكُمْ ) رجوعكم أيها البشر ( جَمِيعاً ) فلا يتخلّف منكم أحد ( وَعْدَ اللهِ حَقًّا ) لا يخلف ما وعد من رجوعكم إليه ( إِنَّهُ ) وحده ( يَبْدَؤُا الْخَلْقَ ) ويوجدهم من العدم ( ثُمَّ يُعِيدُهُ ) بعد موته وفنائه وعدمه ، وإنما يعيده ( لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ ) أي يعطيهم جزاءهم ( بِالْقِسْطِ ) بالعدل ، فإذا لم يروا هنا « في الدنيا » جزاء أعمالهم الصالحة ، لا بد وأن يروا هناك « في الآخرة » ( وَالَّذِينَ كَفَرُوا ) ولم يؤمنوا بالله ( لَهُمْ شَرابٌ مِنْ حَمِيمٍ ) « الحميم » هو الماء الحار الذي انتهى إلى آخر درجة من الحرارة ( وَعَذابٌ أَلِيمٌ ) مؤلم وموجع بسبب ما ( كانُوا يَكْفُرُونَ ) « ما » مصدرية ، أي جزاء على كفرهم. [6] ثم بيّن سبحانه صفاته الفعلية ، وأقام البرهان على الألوهية بما يرى الإنسان من الآثار الكونية البادية للعيان ( هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِياءً ) وَالْقَمَرَ نُوراً وَقَدَّرَهُ مَنازِلَ لِتَعْلَمُوا عَدَدَ السِّنِينَ وَالْحِسابَ أي نورا بالنهار ، ليستفيد منه الإنسان والحيوان والنبات وسائر المخلوقات الأرضية ، ولولاها لم يكن ذو روح على وجه البسيطة ( وَالْقَمَرَ نُوراً ) بالليل ، قالوا : والضياء أبلغ في كشف الظلمات من النور ، وإن كان يطلق كل منهما على الآخر ، إلا أنهما إذا اجتمعا دلّ الأول على زيادة. إن هذا البرهان كاف للإنسان العادي الذي لا يعرف إلا الفطرة السليمة ، كما أنه كاف لأكبر الفلاسفة دقة ، وكذلك جميع آيات القرآن ، فهي في حين تقنع الإنسان البسيط تكون أقوى الحجج للمنطقي والفلسفي والمجادل. فمن يأتري خلق هذه الأشياء ؟ هل أنها صنعت نفسها ؟ إن هذا لا يمكن أبدا ، أم صنعها جاهل عاجز ؟ وهذا كالسابق في الاستحالة. فلا بد وأن يكون صانعها عالم قدير ، وليس هو إلا الله سبحانه. ( وَقَدَّرَهُ ) أي قدر القمر ( مَنازِلَ ) بأن جعل له منازل ، ينزل في أحدهما بعد الآخر حتى يكمل الدور ، وقوله « قدره » إما بحذف « اللام » أي « قدر له » ، وإما مجاز لعلاقة الحال والمحل ، فقد نسب ما للمحل إلى الحال. وإنما قدره منازل ( لِتَعْلَمُوا ) بالقمر ومنازله ( عَدَدَ السِّنِينَ ) فإن السنة تتكون من اثني عشر شهرا ، والشهر لا يكون إلا بحركة القمر من منزل إلى منزل ( وَالْحِسابَ ) حتى تعرفوا أي يوم أول الشهر وأي يوم آخره ، وتضبط بذلك الحسابات والمواعيد. وقد كان القمر والشهور خير وسيلة للعالم والجاهل للضبط والتقدير ، أما سائر الحسابات فهي غير محسوسة بالإضافة إلى كونها خاصة بالعالم. ما خَلَقَ اللهُ ذلِكَ إِلاَّ بِالْحَقِّ يُفَصِّلُ الْآياتِ لِقَوْمٍ يَعْلَمُونَ (5) إِنَّ فِي اخْتِلافِ اللَّيْلِ وَالنَّهارِ وَما خَلَقَ اللهُ فِي السَّماواتِ وَالْأَرْضِ لَآياتٍ لِقَوْمٍ يَتَّقُونَ (6) ( ما خَلَقَ اللهُ ذلِكَ ) الخلق من سماوات وأرض وشمس وقمر ومنازل ( إِلَّا بِالْحَقِ ) فلم يكن الخلق لهوا وعبثا لا طائل فيه ، فإن فيه دلائل على الوحدانية والصفات الأزلية ، كما أن فيه الحساب والميقات والمنافع للخلق ( يُفَصِّلُ ) الله سبحانه ( الْآياتِ ) الدالة على وجوده ويبيّنها آية آية ( لِقَوْمٍ يَعْلَمُونَ ) فيعطون كل آية حقها ، أما الجهّال فإنهم معرضون عن الآيات ( ( وَإِنْ يَرَوْا كُلَّ آيَةٍ لا يُؤْمِنُوا بِها ) (1) . [7] ثم بيّن سبحانه آية أخرى من الآيات الدالة على وجوده مما هو ظاهر للعيان ويعرفه كل إنسان ( إِنَّ فِي اخْتِلافِ اللَّيْلِ وَالنَّهارِ ) والمراد ب « الاختلاف » إتيان أحدهما خلفة للآخر ، كما قال سبحانه في آية أخرى : ( جَعَلَ اللَّيْلَ وَالنَّهارَ خِلْفَةً ) (2) . ولعلّ تقديم الليل ، لأن الظلمة هي السابقة على النور ، فقد قالوا : إن النور والظلمة « عدم وملكة » ومن المعلوم تقدم العدم على الملكة ذاتا ( وَما خَلَقَ اللهُ فِي السَّماواتِ ) من أنواع الكواكب والنيازك والشهب والسحاب والأمطار والرياح وغيرها ( وَالْأَرْضِ ) من أنواع الجبال والمعادن والمياه والنباتات والحيوانات والإنسان وغيرها ( لَآياتٍ ) أي أدلة دالة وبراهين ساطعة على وجود الله سبحانه وصفاته ، من العلم والقدرة والإرادة والحياة وغيرها ( لِقَوْمٍ يَتَّقُونَ ) الانزلاق في مهاوي السفاسف ( 1) الأنعام : 26. ( 2) الفرقان : 63. إِنَّ الَّذِينَ لا يَرْجُونَ لِقاءَنا وَرَضُوا بِالْحَياةِ الدُّنْيا وَاطْمَأَنُّوا بِها وَالَّذِينَ هُمْ عَنْ آياتِنا غافِلُونَ (7) أُولئِكَ مَأْواهُمُ النَّارُ بِما كانُوا يَكْسِبُونَ (8) والخرافة ، كما أن فيهما آيات لمن يتقي عصيان الله سبحانه. وإنما خصّوا بالذكر لأنهم المنتفعون بهذه الآيات. [8] ثم ذكر سبحانه جزاء الذين لا يقتنعون بهذه الآيات ، وينكرون المعاد المستلزم لإنكار المبدأ ( إِنَّ الَّذِينَ لا يَرْجُونَ لِقاءَنا ) أي : لقاء الله ، والمراد ب « لقائه » لقاء الجزاء المقرّر لهم من عنده ، فإن الله سبحانه منزّه عن المكان ، وإنما هو من باب تشبيه المعقول بالمحسوس ، والمراد ب « لا يرجون » لا يتوقعون ، وإنما جيء بهذا اللفظ لأن كل معتقد به يرجو ثواب الله سبحانه ، فإن الإنسان بطبعه يرجو نوال الكريم. وهذا كناية عن عدم الإيمان ، فإن الذين لا يؤمنون لا يرجون المعاد ( وَرَضُوا بِالْحَياةِ الدُّنْيا ) أي الحياة القريبة ، فإن « دنيا » مؤنث « أدنى » أي اختاروا هذه الحياة ، فصرفوا همّهم في عمارتها ، ولا يعملون إلا لها ( وَاطْمَأَنُّوا بِها ) أي سكنوا إليها وركنوا لها. وهذا من عجيب الأمر : كيف يركن الإنسان إلى دنيا يعلم بفنائها السريع ، ويشاهد كل يوم كثرة من الأموات ؟! ( وَالَّذِينَ هُمْ عَنْ آياتِنا ) دلائلنا التي أقمناها على التوحيد وسائر شؤون المبدأ والمعاد ، من الأدلة الكونية وغيرها ( غافِلُونَ ) فلا يتأملون فيها ولا يعتبرون بها.` },
            { text: "إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُدَبِّرُ ٱلْأَمْرَ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ أَفَلَا تَذَكَّرُونَ", tafsir: `` },
            { text: "إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا وَعْدَ ٱللَّهِ حَقًّا إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ بِٱلْقِسْطِ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ يُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ", tafsir: `` },
            { text: "إِنَّ فِى ٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَّقُونَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَٰتِنَا غَٰفِلُونَ", tafsir: `` },
            { text: "أُو۟لَٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ", tafsir: `الذين تلك أوصافهم ( مَأْواهُمُ ) أي مستقرّهم ومرجعهم ( النَّارُ ) إليها يصيرون بسبب ما ( كانُوا يَكْسِبُونَ ) من أنواع الكفر والمعاصي. إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ يَهْدِيهِمْ رَبُّهُمْ بِإِيمانِهِمْ تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهارُ فِي جَنَّاتِ النَّعِيمِ (9) دَعْواهُمْ فِيها سُبْحانَكَ اللهُمَّ وَتَحِيَّتُهُمْ فِيها سَلامٌ [10] هذا هو الكفر ، وهذا مصيره ، فلننظر إلى الإيمان ومصيره ( إِنَّ الَّذِينَ آمَنُوا ) بالله ورسله واليوم الآخر وصدقوا بما جاءت به الأنبياء ( وَعَمِلُوا الصَّالِحاتِ ) أي الأعمال الصالحة ، فإن المحرمات لا تصلح لبناء فرد أو مجتمع أو دنيا أو آخره ، بخلاف الواجبات والمندوبات والمباحات فإنها تصلح لذلك ( يَهْدِيهِمْ رَبُّهُمْ ) بسبب إيمانهم إلى الجنة في الآخرة ، وإلى كل خير في الدنيا ، فإن الإيمان مفتاح كل سعادة ( تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهارُ ) أي تحت أبنيتهم وأشجارهم ، أو من تحت أنفسهم ، باعتبار أن ماء النهر أسفل من الإنسان إذا مشى على الأرض ( فِي جَنَّاتِ النَّعِيمِ ) بحيث يتنعّم الإنسان فيها بجميع أنواع النعم ، من أمن ورفاه وصحة وعلم ولذة وغيرها.` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَٰنِهِمْ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ فِى جَنَّٰتِ ٱلنَّعِيمِ", tafsir: `` },
            { text: "دَعْوَىٰهُمْ فِيهَا سُبْحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ", tafsir: `أي دعاء المؤمنين ، فإن الدعوى قول يدعى به إلى أمر ( فِيها ) أي في تلك الجنات : ( سُبْحانَكَ اللهُمَ ) « سبحان » مصدر منصوب بفعل مقدّر ، أي : أنزّهك تنزيها ، يا الله ، فإن « الميم » في « اللهم » بدل من حرف النداء « يا » ( وَتَحِيَّتُهُمْ ) « التحية » مصدر من باب التفعيل ، بمعنى التكرمة ، مشتقة من : « أحياك الله » ( فِيها ) أي في الجنات ( سَلامٌ ) من الله لهم ، ومن الملائكة بالنسبة إليهم ، ومن بعض المؤمنين لبعض ، و في الدعاء : « حينا ربنا بالسلام » (1) . والمراد ( 1) مستدرك وسائل الشيعة : ج 9 ص 320. وَآخِرُ دَعْواهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعالَمِينَ (10) وَلَوْ يُعَجِّلُ اللهُ لِلنَّاسِ الشَّرَّ اسْتِعْجالَهُمْ بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ ب ـ « السلام » السلامة من الآفات والمكاره ، فإن الجنة هي دار السلام التي لا مكروه فيها أبدا. ومن ذلك سلام الإنسان لبعض حيا أو ميتا ، فإن سلامة الحي من المكاره هنا ، وسلامة الميت من المكاره هناك ، وهو دعاء ، أو تفأّل ، أو رجاء ، بمعنى : « اللهم سلّمه » ، أو : « أتفأّل لك السلامة » ، أو : « أرجوها لك » . ( وَآخِرُ دَعْواهُمْ ) أي آخر كلامهم الذي يتكلمون به ( أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعالَمِينَ ) فهم بين تسبيح وتسليم وتحميد. [12] إن حكمة الله سبحانه اقتضت بقاء الإنسان في الدنيا حتى يبلغ الأجل المضروب له سواء كان صالحا أو طالحا ، فالخيّر والشرير اللذين سبق الكلام حولهما لا بد وأن يتمّا مدتهما المقرّرة لهما ، وإن كان بعض الناس يستعجلون الشرّ بدعائهم ، أو بأعمالهم ( وَلَوْ يُعَجِّلُ اللهُ لِلنَّاسِ الشَّرَّ ) من الموت والمرض والفقر مما يستحقّون بأعمالهم أو بدعائهم ، فإن بعض الناس إذا غضب دعا على نفسه وعلى بعض ذويه بالهلاك والأمراض ونحوهما ( اسْتِعْجالَهُمْ بِالْخَيْرِ ) أي كما يعجّل سبحانه لهم إعطاء الخير الذي يستحقونه بأعمالهم ، أو بدعائهم ( لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ ) أي لفرغ من إهلاكهم ، ولم يكن على وجه الأرض إنسان ، والمعنى : لفرغ من أجلهم ومدّتهم المضروبة للحياة ، وإذا انتهت مدّتهم هلكوا ، كما قال سبحانه : ( وَيَدْعُ الْإِنْسانُ بِالشَّرِّ دُعاءَهُ بِالْخَيْرِ وَكانَ الْإِنْسانُ فَنَذَرُ الَّذِينَ لا يَرْجُونَ لِقاءَنا فِي طُغْيانِهِمْ يَعْمَهُونَ (11) وَإِذا مَسَّ الْإِنْسانَ الضُّرُّ دَعانا لِجَنْبِهِ أَوْ قاعِداً أَوْ قائِماً عَجُولاً ) (1) ، فحيث اقتضت المشيئة الإلهية بقاء الإنسان مدة في الدنيا ( فَنَذَرُ الَّذِينَ لا يَرْجُونَ لِقاءَنا ) من الكافرين الذين لا يعتقدون بالمعاد ( فِي طُغْيانِهِمْ ) عن الحق وترفّعهم عن الإيمان ( يَعْمَهُونَ ) « العمه » هو العمى ، وشدة الحيرة ، فلا نقضي أجلهم بل نمهلهم إمهالا. وهذا الإبقاء إنما هو ليزيد عذابهم حيث طغوا وأعرضوا عن الإيمان بعد ما رأوا الآيات الدالّة عليه. [13] إن الإنسان الذي لم يتأدب بآداب الله سبحانه كثير التناقض ، فبينما تراه يستعجل الشر ، تراه لا يطيق أقل مس من الشر ، حتى أنه إذا أصابه ذلك جعل يدعو الله في كل حالاته لكشفه عنه ( وَإِذا مَسَّ الْإِنْسانَ ) مجرد مسّ وعبور عليه ( الضُّرُّ ) مشقة من مشقات الدنيا في نفس أو أهل أو مال أو نحوها ( دَعانا ) لكشفه وإزالته ، في حال كونه نائما ( لِجَنْبِهِ ) مضطجعا ( أَوْ قاعِداً ) في حال قعوده ( أَوْ قائِماً ) في حال قيامه ، والظاهر أن « أو » هنا بمعنى « الواو » ، فإنها تأتي بمعناها ، قال ابن مالك : خير ، أبح ، قسم ، بأو ، وأبهم و اشكك ، وإضراب بها أيضا نمي و ربما عاقبت الواو إذا لم يلف ذو النطق للبث منفذا ( 1) الإسراء : 12. فَلَمَّا كَشَفْنا عَنْهُ ضُرَّهُ مَرَّ كَأَنْ لَمْ يَدْعُنا إِلى ضُرٍّ مَسَّهُ كَذلِكَ زُيِّنَ لِلْمُسْرِفِينَ ما كانُوا يَعْمَلُونَ (12) وَلَقَدْ أَهْلَكْنَا الْقُرُونَ مِنْ قَبْلِكُمْ لَمَّا ظَلَمُوا وَجاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّناتِ ( فَلَمَّا كَشَفْنا عَنْهُ ضُرَّهُ ) وأزلنا البلاء الذي توجّه إليه ( مَرَّ ) في طريقه السابق ، بدون أن يغيره إلى طريق الدين والحق ( كَأَنْ لَمْ يَدْعُنا إِلى ضُرٍّ مَسَّهُ ) كأن لم يسألنا إزالة ضره ، فهو لا يعرف الرب بعد إزالته. إنه يمرّ بدون أن يتوقف ليشكر ، أو يتذكر ، أو يعتبر ، ( كَذلِكَ ) بمثل هذه الطبيعة المنحطّة التي تتضرّع إلى الله في الضراء ، وتنساه في السراء ( زُيِّنَ لِلْمُسْرِفِينَ ما كانُوا يَعْمَلُونَ ) إن المسرفين الذين أسرفوا في الحياة الدنيا والركون إليها ، ولم يجعلوا للآخرة خط رجعة إليها ، لو وقفوا وتأملوا وشكروا ، ارتدعوا عن أعمالهم الباطلة ، لكنهم يمرّون بلا شكر وتدبّر ، ولذا زيّن الشيطان في نظرهم قبح أعمالهم ، فإن الإنسان إذا تدبر عرف الحسن من القبيح ، أما إذا ركب هواه وسار لا يلوي على شيء ، لا يرى أعماله القبيحة إلا حسنة. [14] فما ذا كانت عاقبة المسرفين ؟ إن السياق يستعرضها بالنسبة إلى الأمم السابقة ، لتعتبر هذه الأمة ( وَلَقَدْ أَهْلَكْنَا الْقُرُونَ ) جمع « قرن » ، وهو أهل كل عصر ، سموا بذلك لمقارنة بعضهم لبعض ، ومنه « القرن » بمعنى الشجاع المقابل لأنه مثل الشجاع الآخر ( مِنْ قَبْلِكُمْ ) بأنواع العذاب ( لَمَّا ظَلَمُوا ) أنفسهم وغيرهم ، وأسرفوا في الركون إلى الدنيا ( وَجاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّناتِ ) أي الحجج والأدلة ، فإن الهلاك إنما وَما كانُوا لِيُؤْمِنُوا كَذلِكَ نَجْزِي الْقَوْمَ الْمُجْرِمِينَ (13) ثُمَّ جَعَلْناكُمْ خَلائِفَ فِي الْأَرْضِ مِنْ بَعْدِهِمْ لِنَنْظُرَ كَيْفَ تَعْمَلُونَ (14) يكون بعد إتمام الحجة ، أما مجرد الظلم بدون إتمام الحجة ، فإنه لا يوجب هلاكا ـ عند الله سبحانه ـ قال : ( وَما كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً ) (1) ، ( وَما كانُوا لِيُؤْمِنُوا ) أي أن هلاكهم بعد العلم بأنهم لا يؤمنون أبدا ، فهم ظالمون قد تمت عليهم الحجة ، ولا يؤمنون بعد ذلك ( كَذلِكَ ) أي كما جازينا أولئك القرون لمّا ظلموا ( نَجْزِي الْقَوْمَ الْمُجْرِمِينَ ) من جميع الأمم.` },
            { text: "وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَٰنِهِمْ يَعْمَهُونَ", tafsir: `` },
            { text: "وَإِذَا مَسَّ ٱلْإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ", tafsir: `` },
            { text: "ثُمَّ جَعَلْنَٰكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ", tafsir: `يا أمة محمد صلى‌الله‌عليه‌وآله‌وسلم ، أو أيها البشر المتأخرون عن أولئك ( خَلائِفَ ) جمع « خليفة » نحو : طرائق جمع طريقة ( فِي الْأَرْضِ مِنْ بَعْدِهِمْ ) من بعد أولئك القرون ، فإنكم خلفتموهم في الأرض ، وصرتم خلفا لهم ( لِنَنْظُرَ ) أي نرى ، والمراد : الرؤية العلمية ، أو الرؤية حقيقة ، فإنه سبحانه ناظر لأعمال العباد ( كَيْفَ تَعْمَلُونَ ) هل تعملون الصالحات أو السيئات ، كأولئك القرون ؟ وإنما نريد النظر للاختيار والجزاء. [16] ثم بيّن سبحانه بعض أعمال هؤلاء المشابهة لأعمال أولئك القرون الظالمة. فقد ذكر بعض المفسرون أن جماعة من المشركين قالوا للنبي صلى‌الله‌عليه‌وآله‌وسلم : ائت بقرآن ليس فيه ترك عبادة اللات والعزى ومناة وهبل ، وليس فيه عيبها ، أو بدّله وتكلم به من تلقاء نفسك (2) . ( 1) الإسراء : 16. ( 2) مجمع البيان : ج 5 ص 166. وَإِذا تُتْلى عَلَيْهِمْ آياتُنا بَيِّناتٍ قالَ الَّذِينَ لا يَرْجُونَ لِقاءَنَا ائْتِ بِقُرْآنٍ غَيْرِ هذا أَوْ بَدِّلْهُ قُلْ ما يَكُونُ لِي أَنْ أُبَدِّلَهُ مِنْ تِلْقاءِ نَفْسِي إِنْ أَتَّبِعُ إِلاَّ ما يُوحى إِلَيَّ إِنِّي أَخافُ إِنْ عَصَيْتُ رَبِّي فنزلت : ( وَإِذا تُتْلى عَلَيْهِمْ ) على هؤلاء الكفار ( آياتُنا ) المنزلة في القرآن ( بَيِّناتٍ ) واضحات ( قالَ الَّذِينَ لا يَرْجُونَ لِقاءَنَا ) أي لا يؤمنون بالمعاد ، فإن المؤمن بالمعاد يرجو فضل الله سبحانه ، فمن لم يرج فليس بمؤمن ، لتلازم الرجاء والإيمان : ( ائْتِ ) جئ يا محمد ( بِقُرْآنٍ غَيْرِ هذا ) القرآن الذي تلوته ( أَوْ بَدِّلْهُ ) فاجعله على خلاف ما تقرأه ، والفرق بينها : أن القرآن الثاني غير مرتبطة مطالبه بالقرآن الأول ، بخلاف « بدله » فهو هو ، لكن مع التبديل كأن يقول ـ عوض ( إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللهِ حَصَبُ جَهَنَّمَ ) (1) ـ : « إنكم وما تعبدون من دون الله زينة الجنة » مثلا. وقد ظن أولئك الجهلة أن القرآن أمثال أشعار العرب التي يتمكن الشاعر أن يقول شعرا آخر ، أو أن يبدل جزءا من الشعر فيجعل مكانه جزءا آخر. ( قُلْ ) يا رسول الله لهم : ( ما يَكُونُ لِي أَنْ أُبَدِّلَهُ ) أبدل القرآن ( مِنْ تِلْقاءِ نَفْسِي ) من ناحية نفسي ، فإنه معجز وذلك بيد الله وحده ، يقال : « فلان تلقاء فلان » أي بحذائه وإزائه ( إِنْ أَتَّبِعُ ) ما أتبع ( إِلَّا ما يُوحى ) أي الشيء الذي يوحيه الله سبحانه ( إِلَيَ ) بلا زيادة ولا نقصان ( إِنِّي أَخافُ إِنْ عَصَيْتُ رَبِّي ) بتبديل كتابه أو تغييره ، أو ( 1) الأنبياء : 99. عَذابَ يَوْمٍ عَظِيمٍ (15) قُلْ لَوْ شاءَ اللهُ ما تَلَوْتُهُ عَلَيْكُمْ وَلا أَدْراكُمْ بِهِ فَقَدْ لَبِثْتُ فِيكُمْ عُمُراً مِنْ قَبْلِهِ أَ فَلا تَعْقِلُونَ (16) سائر أنواع المعاصي ( عَذابَ يَوْمٍ عَظِيمٍ ) يوم القيامة ، وأي معنى للتبديل ؟ هل لأن القرآن ليس معجزا ؟ فليأتوا بمثله ، أم لأن مطالبه وقوانينه ليست مطابقة للواقع أو للحكمة ، فما هو نقدهم فيه ؟ وهل المعاند يكتفي بالتبديل ؟ إن كلامهم كان لمجرد العناد ، وهذا مما لا يصغي إليه الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَٰذَآ أَوْ بَدِّلْهُ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ", tafsir: `` },
            { text: "قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ أَفَلَا تَعْقِلُونَ", tafsir: `يا رسول الله لهؤلاء الذين يطلبون تبديل القرآن : ليس أمر تلاوته ، ولا أمر إنزاله بيدي ، إن جميع شؤون القرآن بيد الله سبحانه ، فهو الذي أنزله ، وهو الذي أمرني بتلاوته ، وقل لهم : إني قد لبثت فيكم قبل نزول القرآن عمرا كاملا أربعين سنة ، ولو كان القرآن مني لكنت أقرأه وأعلمه قبل نزوله ، إن عدم قراءتي له من قبل ، وعدم بيانه سابقا ، دليل على أنه ليس من عندي وليس بيدي حتى أتمكن من تبديله وتغييره ( لَوْ شاءَ اللهُ ) أن لا أتلوه ( ما تَلَوْتُهُ عَلَيْكُمْ ) فإنه هو الآمر بتلاوته عليكم وتبليغكم به ( وَلا أَدْراكُمْ بِهِ ) أي لو شاء الله أن لا تعلموه ، ما أعلمكم به ، وذلك بعدم إنزاله أصلا. فبيده وحده إنزال القرآن ( فَقَدْ لَبِثْتُ ) مكثت وأقمت بينكم و ( فِيكُمْ عُمُراً ) أربعين سنة ( مِنْ قَبْلِهِ ) من قبل قراءتي للقرآن وتلاوتي له ، فلو كان مني لكنت قرأته من قبل ، فإنه أي فارق في كلامي قبل ادعائي للنبوة وبعد ادعائي لها. وقد كان الرسول صلى‌الله‌عليه‌وآله‌وسلم يتكلم بكلام بينهم قبل النبوة فلم يكن يشبه كلامه القرآن أصلا ( أَ فَلا تَعْقِلُونَ ) وتتفكرون في هذه الحقيقة فَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً أَوْ كَذَّبَ بِآياتِهِ إِنَّهُ لا يُفْلِحُ الْمُجْرِمُونَ (17) وَيَعْبُدُونَ مِنْ دُونِ اللهِ ما لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ الواضحة ، فكيف تطلبون مني أن أبدل القرآن. [18] إذن ، لم يبق أمامي في باب تبديل القرآن إلا أن أخترع قرآنا من نفسي ، وهذا مما لا يمكن أبدا ( فَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ ) أي لا أحد أكثر ظلما من إنسان تجرّأ على الله سبحانه ( كَذِباً ) بأن نسب إليه كلاما ليس من كلامه ، أو حكما ليس من حكمه ، فكيف أعمل أنا هذا بأن أخترع قرآنا ثم أنسبه إلى الله تعالى ؟! ( أَوْ كَذَّبَ بِآياتِهِ ) كما تعملون أنتم حيث تكذبون آيات الله وتقولون : أنها ليست من الله ، فكلا الأمرين افتراء عليه ما ليس منه ، وسلب عنه ما هو منه ( إِنَّهُ لا يُفْلِحُ الْمُجْرِمُونَ ) لا يفوزون بخير الدنيا ولا سعادة الآخرة ، فإن الله سبحانه بالمرصاد للمجرم ، خصوصا الاجرام بهذا الحد من الجرأة عليه سبحانه. [19] ثم بيّن سبحانه آلهة هؤلاء الكفار الباطلة ، فإنهم تركوا الحق واتخذوا الباطل ( وَيَعْبُدُونَ ) يعبد هؤلاء الكفار ( مِنْ دُونِ اللهِ ) أي غير الله. وهذا يجتمع مع الشرك ومع الكفر ( ما لا يَضُرُّهُمْ ) ضررا من قبلها ( وَلا يَنْفَعُهُمْ ) فإن الأصنام جمادات لا تضر ولا تنفع ، والعذاب للشرك إنما هو ضرر يتوجه إليهم من عملهم الباطل ، كما أن بعض المنافع المادية لسدنة الأصنام ومن إليهم إنما هي من الأشخاص الباذلين والناذرين لا من قبل الأصنام ، ثم إن كونها « لا تضر ولا تنفع » أبلغ في الردع عن عبادتها ، لأنه لا تجوز العبادة حتى بالنسبة إلى من وَيَقُولُونَ هؤُلاءِ شُفَعاؤُنا عِنْدَ اللهِ قُلْ أَ تُنَبِّئُونَ اللهَ بِما لا يَعْلَمُ فِي السَّماواتِ وَلا فِي الْأَرْضِ سُبْحانَهُ وَتَعالى عَمَّا يُشْرِكُونَ (18) يضر وينفع كعبادة الملوك الذين بيدهم الضر والنفع ظاهرا. أو المراد النافع والضار حقيقة ، وليس في الكون نافع أو ضار في الحقيقة إلا الله سبحانه ، فإنه هو الذي خلق المنافع والمضار وأمكن كل شيء من الإتيان بمقتضاه. ( وَيَقُولُونَ ) أي يقول المشركون وهم الذين يعتقدون بالله وبالصنم : ( هؤُلاءِ شُفَعاؤُنا عِنْدَ اللهِ ) فإنا نعبد هذه الأصنام لتشفع لنا عنده سبحانه ( قُلْ ) يا رسول الله لهؤلاء الكفار : ( أَ تُنَبِّئُونَ اللهَ ) أي هل تخبرون الله سبحانه ـ على نحو الاستفهام الإنكاري ـ ( بِما لا يَعْلَمُ ) فإن الله سبحانه لا يعلم كون الأصنام شافعة ، فكيف تنسبون إليه أنه تعالى جعل الشفاعة لها ، و « لا يعلم » من باب السالبة بانتفاء الموضوع ، فإنه إذا لم يكن موضوع للعلم ، لم يكن علم. فهل يعلم هؤلاء الكفار ما لا يعلمه الله سبحانه ( فِي السَّماواتِ وَلا فِي الْأَرْضِ ) ويخبرونه بما لا وجود له ؟ ويخترعون الشفاعة لما لم يجعله الله سبحانه شفيعا ( سُبْحانَهُ ) منزّه عن ذلك ( وَتَعالى ) إنه أعلى وأجل ( عَمَّا يُشْرِكُونَ ) من أن يكون له شريك ، و « ما » إما مصدرية ، أي عن شركهم ، فهو منزّه عن شركهم وأجلّ منه. وإما موصولة ، أي عن الأصنام التي يشركونها مع الله ، فهو منزّه عن المثل ، وأعلى وأجل من أن يكون في عداد الأصنام. [20] وقبل أن يستعرض القرآن سائر أقوالهم السخيفة ، يبيّن أن الشرك وَما كانَ النَّاسُ إِلاَّ أُمَّةً واحِدَةً فَاخْتَلَفُوا وَلَوْ لا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَقُضِيَ بَيْنَهُمْ فِيما فِيهِ يَخْتَلِفُونَ (19) وَيَقُولُونَ لَوْ لا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ عارض على البشر ، وإلّا فالفطرة السليمة تدل على التوحيد ، فإن الجهاز الموحّد المنظّم يدل على إرادة موحدة ورئيس واحد ( وَما كانَ النَّاسُ ) بفطرتهم وأصلهم ( إِلَّا أُمَّةً واحِدَةً ) موحدة ، كما قال النبي صلى‌الله‌عليه‌وآله‌وسلم : « كل مولود يولد على الفطرة إلا أن أبويه هما اللذان يهودانه وينصرانه ويمجسانه » (1) ، ( فَاخْتَلَفُوا ) بأن بقي بعضهم على التوحيد ، وانحرف بعضهم نحو الشرك. ( وَلَوْ لا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ ) بأن قالها وقرّرها بأن تكون الدنيا دار امتحان ، فيكون الناس فيها مختارين مطلقي السراح مهما شاءوا اعتقدوا ، ومهما أرادوا عملوا ، حتى يكون الجزاء عدلا واستحقاقا ، لا محاباة واعتباطا ( لَقُضِيَ بَيْنَهُمْ ) أي حكم الله بينهم في هذه الدنيا بأن يهلك المشركين ويذر الموحدين ( فِيما فِيهِ يَخْتَلِفُونَ ) من التوحيد والشرك ، أو المراد : لقضي بينهم بأن أجبر الجميع على التوحيد ، لكنه ( ( لا إِكْراهَ فِي الدِّينِ ) (2) .` },
            { text: "فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ", tafsir: `` },
            { text: "وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ", tafsir: `` },
            { text: "وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ", tafsir: `` },
            { text: "وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ", tafsir: `أي يقول هؤلاء الكفار : ( لَوْ لا أُنْزِلَ عَلَيْهِ ) أي على الرسول صلى‌الله‌عليه‌وآله‌وسلم ( آيَةٌ ) معجزة خارقة كمعاجز عيسى وموسى عليهما‌السلام ( مِنْ ) طرف ( رَبِّهِ ) فقد كانوا يقترحون خوارق أخرى ، وكان ذلك منهم تعنّتا ، ( 1) بحار الأنوار : ج 58 ص 187. ( 2) البقرة : 257. فَقُلْ إِنَّمَا الْغَيْبُ لِلَّهِ فَانْتَظِرُوا إِنِّي مَعَكُمْ مِنَ الْمُنْتَظِرِينَ (20) وَإِذا أَذَقْنَا النَّاسَ رَحْمَةً مِنْ بَعْدِ ضَرَّاءَ مَسَّتْهُمْ إِذا لَهُمْ مَكْرٌ فِي آياتِنا إذ يكفي في الدلالة الخارقة دلالة القرآن العظيم المعجزة الباقية ، لكنهم لم يكونوا يذعنون لها ( فَقُلْ ) يا رسول الله : ( إِنَّمَا الْغَيْبُ لِلَّهِ ) إن الآية الخارقة التي تطلبونها غيب خارق لقوانين هذا الكون ، وإنه بيد الله سبحانه ليس بيدي ومن عندي ، وهو أعلم بالمصالح ( ( وَما يُشْعِرُكُمْ أَنَّها إِذا جاءَتْ لا يُؤْمِنُونَ ) (1) ، فإن المتعنّت لا يريد إلا اللّجاج لا الحجة والاقتناع حتى يسير الإنسان حيث إرادته ، إنه لو أراد الاقتناع والدلالة لكفته هذه المعجزة العظيمة ، فهو كمن يأتي بإمضاء الرئيس ، ثم يقول الناس له : « جئ بإمضاء آخر حتى نقبل قولك » ( فَانْتَظِرُوا ) المستقبل حتى ترون هل يأتي الله سبحانه بما تطلبون ( إِنِّي مَعَكُمْ مِنَ الْمُنْتَظِرِينَ ) وهذا الجواب فيه شبه تهديد ، كما تقول للمجرم : اصبر حتى نرى العاقبة. [22] ثم بيّن سبحانه أن الطبيعة البشرية إنما تطغى إذا رأت نفسها غنية غير محتاجة ، أما إذا وقع الإنسان في أزمة وشدة ، فهو يلوذ بالله ويتوسل إليه ، وهذا دليل على ما كمن في فطرته من التوحيد والاعتراف بالألوهية ( وَإِذا أَذَقْنَا النَّاسَ رَحْمَةً ) « الإذاقة » تستعمل بمعنى الذوق باللسان ، كما تستعمل بمعنى الإدراك مطلقا ، وهذا هو المراد هنا ، فإن الرحمة ليست خاصة باللسان ( مِنْ بَعْدِ ضَرَّاءَ مَسَّتْهُمْ ) من شدة أو فاقة أو اضطراب أو غيرها ( إِذا لَهُمْ مَكْرٌ فِي آياتِنا ) فإنهم حيث رأوا الشدة ( 1) الأنعام : 110. قُلِ اللهُ أَسْرَعُ مَكْراً إِنَّ رُسُلَنا يَكْتُبُونَ ما تَمْكُرُونَ (21) هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ وَالْبَحْرِ كانوا جديرين بقبول الحق ، واتباع الرسل ، والأخذ بالأحكام ، لكن طبيعتهم العاتية حيث ترى غناها بسبب الرحمة التي ذاقتها ، ترجع إلى إنكار الآيات ، والاحتيال والمكر لإخمادها وإنكارها ، وقد كانت عادة البشر هكذا مع الأنبياء ، فقوم فرعون كلما أصيبوا بمكروه جاءوا إلى موسى عليه‌السلام يسألونه الكشف عنهم حتى يؤمنوا ، فإذا أذاقهم الله الرحمة ، وكشف عنهم العذاب رجعوا إلى ما كانوا عليه ، وأخذوا يمكرون بموسى ، ويحتالون لإخماد آيات الله سبحانه ، وهكذا سائر الأنبياء والمصلحين مع أممهم ، إلى هذا اليوم. ( قُلِ ) يا رسول الله ، لمثل هؤلاء : لا تفعلوا ولا تمكروا ف ( اللهُ أَسْرَعُ مَكْراً ) فإن مكر هؤلاء لا يصل إلى أعماق الحياة ، بخلاف مكره سبحانه وعلاجه للأمر ـ لأن المكر هو : التدبير الخفي ـ فإنه يصل إلى أعماق الحياة ، ولذا تكون جذور دعوات الأنبياء أعمق وأسرع في نفوس الناس من مكر الماكرين وإنكار الملحدين وتشكيك المشككين ( إِنَّ رُسُلَنا ) أي الملائكة ( يَكْتُبُونَ ما تَمْكُرُونَ ) أي ما تدبرون خفية ضد الدين وأهله ، ثم تجزون على ذلك. [23] ثم ضرب سبحانه مثلا لطبيعة الإنسان العاتية التي تتضرع عند الشدة ، وتنسى عند الرخاء ( هُوَ الَّذِي يُسَيِّرُكُمْ فِي الْبَرِّ ) فإن مشي الحيوان ، والمركبة ، وغيرها ، إنما هو حسب تكوين الله سبحانه ونظامه الذي جعله للحياة وإلا لم يتمكن الإنسان من السير ولو خطوة واحدة ( وَالْبَحْرِ ) بسبب الفلك ونظام عدم غرق ما وزن الماء أثقل منه ـ كما حَتَّى إِذا كُنْتُمْ فِي الْفُلْكِ وَجَرَيْنَ بِهِمْ بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا بِها جاءَتْها رِيحٌ عاصِفٌ وَجاءَهُمُ الْمَوْجُ مِنْ كُلِّ مَكانٍ وَظَنُّوا أَنَّهُمْ أُحِيطَ بِهِمْ بيّن في قانون أرخميدس ـ ( حَتَّى إِذا كُنْتُمْ فِي الْفُلْكِ ) فكأن الإنسان سار من بلده في طريق البحر حتى ركب في السفينة لإرادة الذهاب إلى مقصد من مقاصده البعيدة ( وَجَرَيْنَ ) أي جرت السفن ، فإن « الفلك » يأتي مفردا وجمعا بلفظ واحد ( بِهِمْ ) أي بالناس ( بِرِيحٍ طَيِّبَةٍ ) لينة يستطيبونها ، لأنها تجري نحو المقصد في رخاء وهدوء ( وَفَرِحُوا ) الراكبون ( بِها ) أي بهذه الريح. فهم في أمن وفرح وسير نحو المقصد بارتياح ، وإذا بهم ( جاءَتْها ) السفينة ( رِيحٌ عاصِفٌ ) شديدة الهبوب ، هائلة هائجة ، فأخذت السفينة في الاضطراب والإشراف على الغرق من الترنّح الشديد الذي يصيبها بسبب تلاطم الأمواج ( وَجاءَهُمُ الْمَوْجُ مِنْ كُلِّ مَكانٍ ) من الأطراف الأربعة ، فإن الرياح إذا توجهت نحو الماء رفعت منه أجزاء كثيرة ربما صارت كالجبل العظيم ، وهذا هو الموج ، والأمواج تسير بسير الهواء ما دامت تنفخ فيها وتسيّرها ، فإذا اضطربت الرياح وهبت من الجهات المختلفة جاءت الموج من كل مكان ، وإذا بالسفينة في وسط الأمواج ترتفع مرة وتنحدر أخرى ، وتميل ثالثة ، وتقع من علو دفعة ـ إذا تلاشت الأمواج تحتها ـ رابعة ، وهكذا .. فتصبح : كريشة في مهب الريح طائفة لا تستقر على حال من القلق ( وَظَنُّوا أَنَّهُمْ أُحِيطَ بِهِمْ ) أي أحاطت بهم الأمواج بحيث تغرقهم دَعَوُا اللهَ مُخْلِصِينَ لَهُ الدِّينَ لَئِنْ أَنْجَيْتَنا مِنْ هذِهِ لَنَكُونَنَّ مِنَ الشَّاكِرِينَ (22) فَلَمَّا أَنْجاهُمْ إِذا هُمْ يَبْغُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ يا أَيُّهَا النَّاسُ إِنَّما بَغْيُكُمْ عَلى أَنْفُسِكُمْ مَتاعَ الْحَياةِ الدُّنْيا ثُمَّ إِلَيْنا مَرْجِعُكُمْ فَنُنَبِّئُكُمْ بِما كُنْتُمْ تَعْمَلُونَ (23) فلا نجاة من الهلكة ، وحينئذ حيث رأوا الهلاك ( دَعَوُا اللهَ ) وتضرعوا إليه ، وانقشعت عن عيونهم غواشي الشهوات والأنانيات ، وظهرت فطرتهم صافية ( مُخْلِصِينَ لَهُ الدِّينَ ) أي على وجه الإخلاص في الاعتقاد ، بحيث يجعلون الدين له ، وينقطعون عما سواه ، قائلين : ( لَئِنْ أَنْجَيْتَنا ) يا رب ( مِنْ هذِهِ ) الشدة والورطة ( لَنَكُونَنَّ مِنَ الشَّاكِرِينَ ) المعترفين بك وبفضلك وإحسانك فإن الشكر يستلزم الإذعان والتوحيد.` },
            { text: "وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ", tafsir: `` },
            { text: "فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم مَّتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `أي خلّصهم من تلك الأهوال ( إِذا هُمْ يَبْغُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِ ) أي يظلمون أنفسهم وغيرهم ، فإن من لا يسير على منهاج الله سبحانه لا بد وأن يكون ظالما باغيا ( يا أَيُّهَا النَّاسُ إِنَّما بَغْيُكُمْ عَلى أَنْفُسِكُمْ ) فإن ظلم الظالم يعود وباله عليه ( مَتاعَ الْحَياةِ الدُّنْيا ) أي أن بغيكم إنما هو ما يتمتّع به في الحياة الدنيا ، وذلك منقطع لا يبقى ، فإن الإنسان إنما يبغي لأمور دنيوية ، ولا فائدة فيما لا بقاء له ولا دوام ( ثُمَّ إِلَيْنا مَرْجِعُكُمْ ) رجوعكم ومصيركم ( فَنُنَبِّئُكُمْ ) نخبركم ( بِما كُنْتُمْ تَعْمَلُونَ ) وهذا تهديد بأنهم سيجازون بأعمالهم السيئة ، كما تقول للمجرم : « سأخبرك بأعمالك » تريد جزاءه إِنَّما مَثَلُ الْحَياةِ الدُّنْيا كَماءٍ أَنْزَلْناهُ مِنَ السَّماءِ فَاخْتَلَطَ بِهِ نَباتُ الْأَرْضِ مِمَّا يَأْكُلُ النَّاسُ وَالْأَنْعامُ حَتَّى إِذا أَخَذَتِ الْأَرْضُ زُخْرُفَها وَازَّيَّنَتْ وَظَنَّ أَهْلُها أَنَّهُمْ قادِرُونَ عَلَيْها على تلك السيئات التي صدرت منه. [25] ولما ذكر سبحانه أن الظلم إنما هو متاع الحياة الدنيا ، بيّن فناءها ، وأنه لا ينبغي أن يعمل الإنسان لما يفنى ولا يبقى ( إِنَّما مَثَلُ الْحَياةِ الدُّنْيا ) أي شبه الحياة القريبة في سرعة فنائها وزوالها ( كَماءٍ أَنْزَلْناهُ مِنَ السَّماءِ ) وهو المطر ( فَاخْتَلَطَ بِهِ نَباتُ الْأَرْضِ ) فإن النبات يمتص الماء حتى ينضر ويزدهر وينمو ( مِمَّا يَأْكُلُ النَّاسُ ) من الثمار والبقول ونحوهما ( وَالْأَنْعامُ ) كالحشيش والقات وغيرهما. ولعل الإتيان بهذا التفصيل للتناسق بين المثال والممثل له فكما أن الماء يختلط بالأجناس العالية من النبات ـ وهو مأكل الإنسان ـ والأجناس السافلة ـ وهو مأكل الحيوان ـ كذلك الحياة التي يفيضها الله سبحانه على الكون تختلط بالأشياء الراقية كالإنسان والجواهر ، وبالأشياء المنحطة كالمدر والحجر وغيرهما. ( حَتَّى إِذا أَخَذَتِ الْأَرْضُ زُخْرُفَها ) « الزخرف » كمال حسن الشيء ، يقال : «زخرفته » أي حسنته ، فإن المطر لما ينزل من السماء يظهر ريع الزروع والكروم ونضارة النباتات والأشجار ( وَازَّيَّنَتْ ) أي تزينت الأرض بالنبات الزاهي والزرع النضر ، وأصل «ازينت » تزينت من باب « التفعل » قلبت « التاء » « زاء » وجيء بهمزة الوصل لتعذر الابتداء بالساكن. ( وَظَنَّ أَهْلُها ) أي أهل الأرض ( أَنَّهُمْ قادِرُونَ عَلَيْها ) لزعمهم أَتاها أَمْرُنا لَيْلاً أَوْ نَهاراً فَجَعَلْناها حَصِيداً كَأَنْ لَمْ تَغْنَ بِالْأَمْسِ كَذلِكَ نُفَصِّلُ الْآياتِ لِقَوْمٍ يَتَفَكَّرُونَ (24) أنهم هم الذين أوجدوها بجهدهم ، وزيّنوها بصنعهم ، وأنهم مالكوا الأمر فيها ، فلا يتمكن أحد من تغييرها وتحريرها. وكذلك الإنسان دائما يظن أن ما يجري في الكون مما له دخل فيه ، إنما هو بصنعه وإرادته ، فإذا بنى دارا زعم أنها صنعه ، وإذا جرت سفينته في الماء ظن أنها منه ، وهكذا ، والحال أن الإنسان ليس إلا جزءا صغيرا متوسطا في سلسلة العلل. فقبله ، الأرض التي منها أدوات البناء وبعده الصورة التي هي من الله سبحانه ، وبها البقاء للدار ، وهكذا بالنسبة إلى السفينة وسائر الأشياء. ( أَتاها ) أتى تلك الأرض المزخرفة بالزرع والنظارة ( أَمْرُنا ) أي عذابنا من برد أو ثلج أو عاصفة أو جراد أو نحوها ( لَيْلاً أَوْ نَهاراً ) وهذا يدل على كمال القدرة ، فإنه لا يخشى من أحد ولا يمنعه وقت يقظة الناس كما لا يمنعه حراس الليل ( فَجَعَلْناها حَصِيداً ) جعلنا تلك الأرض حصيدا أي محصودة ، مقلوعة ذاهبة ( كَأَنْ لَمْ تَغْنَ ) لم توجد ولم تكن ( بِالْأَمْسِ ) من قبل ، من « غني بالمكان » بمعنى أقام به ، ومنه « المغنى » بمعنى المنزل ( كَذلِكَ ) بما فصلنا هذا المثال وأوضحناه ( نُفَصِّلُ ) سائر ( الْآياتِ لِقَوْمٍ يَتَفَكَّرُونَ ) في أدلة الله سبحانه ، فالحياة الدنيا ، كماء المطر والدنيا كالمزرعة ، فإن الحياة تختلط بماهية الأشياء ، وإذ نرى الحياة مزدهرة ، والأسواق عامرة ، والأرض مخضرة ، والناس في أمن ورفاه ، وأخذ وعطاء ، وفي هذه الغمرة من الحسن والازدهار ، وإذا بأمر الله سبحانه يأتي إما بسبب أرضي وَاللهُ يَدْعُوا إِلى دارِ السَّلامِ وَيَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ (25) لِلَّذِينَ أَحْسَنُوا كالخسف ، أو بسبب سماوي كالصيحة والبرق والقذف ، أو كالأمراض الفتاكة ، أو كالوسائل الهدامة من الآلات الحربية المفنية ـ كالقنابل وغيرها ـ فيجعلها حصيدا لا حياة فيها ولا حركة ، ولا عمارة ولا حضارة .. أليس الأمر كذلك ؟ وأليس يكفي هذا دلالة على وجود الله وقدرته ؟ فكيف يتكبر الإنسان ويعصي ، ويطغى ويكفر ؟ [26] هذه كانت حالة الدنيا فهي دار تغير وزوال ، وفناء واضمحلال ( وَاللهُ يَدْعُوا ) الناس ( إِلى دارِ السَّلامِ ) التي يكون كل شيء فيها سالما عن التغير والآفات ، وهي الجنة ، فإنه سبحانه يحرّضهم للعمل ، فهذه الدار لتلك الدار ، و « السلام » و « السلامة » بمعنى واحد ، كالرضاع والرضاعة ( وَيَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ ) إما المراد بالهداية : معناها العام ، ف « من يشاء » هم جميع الناس ، وإما المراد بها : معناها الخاص ، أي الألطاف الخاصة ، ف « من يشاء » هم الذين اتخذوا مناهج الأنبياء ، فإنهم مختصون بتلك الألطاف المؤدية بهم إلى جنات النعيم. ومن المحتمل أن يراد بالهداية : معناها العام ـ وهي إراءة الطريق ـ ويكون « من يشاء » خاصا بمن تمّت لديه الحجة ، فإن كثيرا من أهل البلاد البعيدة لم تبلغهم الدعوة ، وكذلك من مات في الفترة بين الرسل ونحوهم ، وأولئك الذين لم تبلغهم الدعوة ، إنما يمتحنون يوم القيامة ، كما يقتضيه العدل ، ودلّ على بعض موارده الدليل. [27] تلك حال الدنيا الزائلة وهذه حال الآخرة الباقية ، فلننظر إلى أحوال أهل تلك ، وأهل هذه بين الأمرين ، ف ( لِلَّذِينَ أَحْسَنُوا ) الاعتقاد ، الْحُسْنى وَزِيادَةٌ وَلا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلا ذِلَّةٌ أُولئِكَ أَصْحابُ الْجَنَّةِ هُمْ فِيها خالِدُونَ (26) وَالَّذِينَ كَسَبُوا السَّيِّئاتِ وأحسنوا العمل ، بأن آمنوا وعملوا الصالحات ( الْحُسْنى ) أي الحالة الحسنى ، فإنهم يجزون بإحسانهم إحسانا ( وَزِيادَةٌ ) فضل من الله سبحانه ، فمن جاء بالحسنة فله عشر أمثالها ، كما قال سبحانه في آية أخرى : ( لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُمْ مِنْ فَضْلِهِ ) (1) ، ( وَلا يَرْهَقُ ) « الرهق » لحاق الأمر ، ومنه « راهق الغلام » إذا لحق بالرجال ، ويستعمل اسما من « الإرهاق » وهو أن يحتمل الإنسان ما لا يطيقه ، أي لا يلحق ( وُجُوهَهُمْ قَتَرٌ ) أي غبار وسواد ( وَلا ذِلَّةٌ ) انكسار وانهزام ، فليست كوجوه أهل المعاصي التي يظهر عليها أثر العذاب الجسدي بالقتر ، وأثر العذاب النفسي بالذلة ، بل وجوههم نضرة ، كما قال سبحانه : ( تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ ) (2) ، ( أُولئِكَ ) الذين أحسنوا ( أَصْحابُ الْجَنَّةِ ) رفاقها وملاكها ( هُمْ فِيها خالِدُونَ ) دائمون أبدا ، لا خروج لهم منها ، ولا تغيّر لها بهم.` },
            { text: "إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَتَفَكَّرُونَ", tafsir: `` },
            { text: "وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `` },
            { text: "لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `أي عملوها ، وغالبا يأتي « الكسب » بالنسبة إلى السيئات للدلالة على صعوبة السيئات بخلاف الحسنات ، وذلك واضح لأن السيئات لها التواءات توجب الصعوبة لمكتسبها فمثلا الزواج فيه سهولة اطمئنان النفس إلى دار ، وأهل ، وأولاد ، وقلوب تحنو عليه ، ومستقبل يقوم به النسل ، وذكر جميل وسيادة. والسفاح بالعكس من كل ذلك ، بالإضافة إلى صرف المال والطاقة لقلب خاو ( 1) فاطر : 31. ( 2) المطففين : 25. جَزاءُ سَيِّئَةٍ بِمِثْلِها وَتَرْهَقُهُمْ ذِلَّةٌ ما لَهُمْ مِنَ اللهِ مِنْ عاصِمٍ كَأَنَّما أُغْشِيَتْ وُجُوهُهُمْ قِطَعاً مِنَ اللَّيْلِ مُظْلِماً أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (27) وعمل مذموم ، وهكذا. وليس المقصود أن الحلال بلا صعوبة ، وأن الحرام بلا لذة ، وإنما المقصود أن الحلال دائما أهنأ وأسهل من الحرام ، فإنه سبحانه خلط الحرام باللذة القليلة ، والحلال بالتعب اليسير ، ليختبر ويمتحن ، فلو كان الحلال بلا تعب لم يكن الآتي به ممدوحا ، ولو كان الحرام بلا لذة لم يكن التارك له مستحقا للأجر والثواب. ( جَزاءُ سَيِّئَةٍ بِمِثْلِها ) لا يجازون بأكثر من عملهم ، إذ الجزاء بالأكثر ظلم قبيح ، و « جزاء » مبتدأ خبره « بمثلها » ، والجملة خبر لقوله : « الذين كسبوا » والعائد محذوف أي « لهم » ونحوه ( وَتَرْهَقُهُمْ ذِلَّةٌ ) تلحقهم ذلة نفسية ، فإن الإنسان المعذّب يحس في نفسه ذلة وانهزاما ( ما لَهُمْ مِنَ اللهِ مِنْ عاصِمٍ ) ليس يحفظهم عن العذاب اللاحق بهم حافظ من قبل الله ، أو المراد : لا ينجيهم من عذاب الله حافظ ، وهم بالإضافة إلى العذاب والصعوبات ، فإن الدم يحترق في الجسد ، وينقلب أسودا ، فيظهر لونه على الجسم لشفافية الجلد ( كَأَنَّما أُغْشِيَتْ وُجُوهُهُمْ قِطَعاً مِنَ اللَّيْلِ مُظْلِماً ) فكأن الليل صار قطعا بسواده الشديد ، فأغشيت وجوههم بقطع منه ، قطعة فوق قطعة حتى لا يرى فيها أثر النور والضياء ، فهم في عذاب البدن ، وذلة النفس ، وسواد الوجه ( أُولئِكَ ) الذين كسبوا السيئات ( أَصْحابُ النَّارِ ) رفاقها والملازمون لها والمعرّفون بها ( هُمْ فِيها خالِدُونَ ) دائمون أبد الآبدين. وَيَوْمَ نَحْشُرُهُمْ جَمِيعاً ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا مَكانَكُمْ أَنْتُمْ وَشُرَكاؤُكُمْ فَزَيَّلْنا بَيْنَهُمْ وَقالَ شُرَكاؤُهُمْ ما كُنْتُمْ إِيَّانا تَعْبُدُونَ (28) [29] قد كان أولئك الكفار والعصاة في الدنيا لهم آلهة وأصدقاء ، فأين ذهبت آلهتهم وأصدقاؤهم ؟ وهل أنقذوهم وشفّعوا فيهم ؟ إنهم هناك انقلبوا أعداء بعد ما رأوا العذاب ( وَ ) اذكر ( يَوْمَ نَحْشُرُهُمْ ) أي نجمعهم ( جَمِيعاً ) بلا استثناء أحد ، وهو يوم القيامة ( ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا ) بالله ، بأن جعلوا له شريكا : الزموا ( مَكانَكُمْ ) لا تبرحوا حتى تجازون بأعمالكم ( أَنْتُمْ وَشُرَكاؤُكُمْ ) أي كونوا جميعا في مكانكم حتى تعطون الجزاء. وإضافة الشركاء إليهم باعتبار أنهم اخترعوها ، وجعلوها شركاء الله سبحانه ( فَزَيَّلْنا بَيْنَهُمْ ) أي ميّزنا وفرّقنا ، والمراد : التفريق بينهم في السؤال ، فهناك سؤال عن المشركين ، وسؤال عن الآلهة التي عبدوها من دون الله سبحانه ( وَقالَ شُرَكاؤُهُمْ ) الأصنام وغيرها من المعبودات التي عبدوها ، مخاطبين للكفار : ( ما كُنْتُمْ ) أيها المشركون ( إِيَّانا تَعْبُدُونَ ) إما المراد أنهم عبدوا الأهواء والشياطين ، وإما المراد نفي ذلك ، مريدا به نفي العلم بعبادتهم. وهذا أيضا يصح بالنسبة إلى من لا يعلم ، كالأصنام التي لا تعقل ، فإنها ينطقها الله سبحانه هناك ، أو أنهم يكذبون للتخلص من التبعة حتى لا يقال لهم : لم رضيتم بعبادة هؤلاء لكم ؟ كما يكذب المشركون هناك قائلين : ( وَاللهِ رَبِّنا ما كُنَّا مُشْرِكِينَ ) (1) . ( 1) الأنعام : 24. فَكَفى بِاللهِ شَهِيداً بَيْنَنا وَبَيْنَكُمْ إِنْ كُنَّا عَنْ عِبادَتِكُمْ لَغافِلِينَ (29) هُنالِكَ تَبْلُوا كُلُّ نَفْسٍ ما أَسْلَفَتْ وَرُدُّوا إِلَى اللهِ مَوْلاهُمُ الْحَقِّ وَضَلَّ عَنْهُمْ ما كانُوا يَفْتَرُونَ (30) [30] ثم يستشهد المعبودون بالله سبحانه في أنهم لم يكونوا يعلمون بعبادة المشركين لهم ( فَكَفى بِاللهِ شَهِيداً ) أي يكفينا شاهدا وفاصلا للحق ( بَيْنَنا ) معاشر المعبودين ( وَبَيْنَكُمْ ) أيها المشركون ( إِنْ كُنَّا عَنْ عِبادَتِكُمْ ) أيها المشركون لنا ( لَغافِلِينَ ) « إن » مخففة من المثقلة ، وحذف اسمها ، وهو ضمير الشأن أي يشهد الله : أنه كنا غافلين عن عبادتكم لنا ، فإنا لم نعلم بذلك ، فكيف نرضى به ؟ ولا إثم علينا من هذه الجهة. وهذه حجة قوية على المشركين في الدنيا ، فإنهم يعبدون ما لا يعلم شيئا من عبادتهم ، وهل يصلح للعبادة ما هذا شأنه ؟!` },
            { text: "وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ فَزَيَّلْنَا بَيْنَهُمْ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ", tafsir: `` },
            { text: "فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ", tafsir: `` },
            { text: "هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ", tafsir: `في ذلك الموقف الرهيب موقف الحشر ( تَبْلُوا كُلُّ نَفْسٍ ما أَسْلَفَتْ ) أي تختبر كل نفس أعمالها التي أسلفتها وقدمتها ، فإن الإنسان في الدنيا لم يختبر أعماله ، ولا يعلم الصالح والفاسد منها إلا قليلا ، إلّا إذا كان متّبعا للأنبياء فيعرف قيمة الأعمال ، فمثلا لا يعلم الإنسان في الدنيا قيمة الصدقة ، إذ لم يختبرها حتى يعرف ما الثمار الكثيرة المترتبة عليها ، كما لا يعرف مقدار ضرر الشرك وما أشبه ( وَرُدُّوا إِلَى اللهِ مَوْلاهُمُ الْحَقِ ) أي ارجعوا إليه ، إلى ثوابه وعقابه ، وحسابه وجزائه ( وَضَلَّ عَنْهُمْ ) أي ضاع وبطل عن نصرتهم وشفاعتهم وإنقاذهم ( ما كانُوا يَفْتَرُونَ ) أي الأصنام والمعبودات الباطلة التي كانوا يفترون على الله سبحانه بكونها شركاء له. [32] ثم يستدل سبحانه على كونه الحق وأن سواه باطل بما يشاهدونه في قُلْ مَنْ يَرْزُقُكُمْ مِنَ السَّماءِ وَالْأَرْضِ أَمَّنْ يَمْلِكُ السَّمْعَ وَالْأَبْصارَ وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَنْ يُدَبِّرُ الْأَمْرَ فَسَيَقُولُونَ اللهُ فَقُلْ أَ فَلا تَتَّقُونَ (31) حياتهم اليومية ( قُلْ ) يا رسول الله لهؤلاء المشركين : ( مَنْ يَرْزُقُكُمْ ) ويعطي أرزاقكم ( مِنَ السَّماءِ ) بإنزال المطر ( وَالْأَرْضِ ) بإخراج النبات ، وهكذا يشمل الرزق طيور السماء وأسماك الماء وحيوانات الصحراء ، أو هو أعم من ذلك ومن سائر الأشياء التي يستفاد منها كالدور والقصور ، والمراكب والملابس ، وغيرها ( أَمَّنْ يَمْلِكُ السَّمْعَ وَالْأَبْصارَ ) فإن من وهبهما وأبقاهما ليس إلا الله سبحانه ، وهو القادر على أن يسلبهما ( وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ ) كالنباتات من الأرض ، والإنسان والحيوان من المأكولات الميتة ، أو ما أشبه ذلك ( وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِ ) كالثمار والحبوب من النباتات ، والجنين الميت من المرأة الحية ، أو ما أشبه ذلك ( وَمَنْ يُدَبِّرُ الْأَمْرَ ) أمر السماء والأرض بانتظام الحركات وتسيير الأجهزة ، على وجه الحكمة والصلاح. ( فَسَيَقُولُونَ اللهُ ) يفعل كل ذلك ، فإنهم بصفتهم مشركون كانوا معترفين بالله ، حيث لم تكن الأصنام وما أشبهها تقدر على هذه الأشياء الكبيرة ، فلا بد وأن يعترفوا بأنها من الله سبحانه وحده ، لا شريك له في ذلك كله ( فَقُلْ ) يا رسول الله لهم : ( أَ فَلا تَتَّقُونَ ) في جعلكم الشريك له بغير علم ، أ فلا تخافون عقابه وعذابه في شرككم بلا حجة ولا برهان ؟. فَذلِكُمُ اللهُ رَبُّكُمُ الْحَقُّ فَما ذا بَعْدَ الْحَقِّ إِلاَّ الضَّلالُ فَأَنَّى تُصْرَفُونَ (32) كَذلِكَ حَقَّتْ كَلِمَةُ رَبِّكَ عَلَى الَّذِينَ فَسَقُوا أَنَّهُمْ لا يُؤْمِنُونَ (33) قُلْ هَلْ مِنْ شُرَكائِكُمْ` },
            { text: "قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ فَسَيَقُولُونَ ٱللَّهُ فَقُلْ أَفَلَا تَتَّقُونَ", tafsir: `` },
            { text: "فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَٰلُ فَأَنَّىٰ تُصْرَفُونَ", tafsir: `أي ذاك الموصوف بتلك الصفات ـ أيها المخاطبون ـ فإن « كم » للخطاب ( اللهُ رَبُّكُمُ ) وإلهكم ( الْحَقُ ) الذي خلقكم ورزقكم ولا يستحق العبادة أحد سواه ( فَما ذا بَعْدَ الْحَقِّ إِلَّا الضَّلالُ ) استفهام تقريري ، أي ليس وراء الحق إلا باطل ، فالله الحق ، ودونه باطل ( فَأَنَّى ) إلى أين ( تُصْرَفُونَ ) يصرفكم الشيطان والأهواء ، فتعدلون عن الحق وهو الإله الواحد إلى الآلهة المتعددة.` },
            { text: "كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ", tafsir: `الذي تقدم من قيام الأدلة عند هؤلاء المشركين على التوحيد ، ومع ذلك لا يقبلون النتيجة ويجعلون مع الله شركاء ( حَقَّتْ كَلِمَةُ رَبِّكَ ) ثبتت ، ووجبت كلمة الله وحكمه والعلم الأزلي ( عَلَى الَّذِينَ فَسَقُوا ) وخرجوا عن طاعة الله الواحد إلى طاعة الأنداد وعبادة الأصنام ( أَنَّهُمْ لا يُؤْمِنُونَ ) هذا بدل من « كلمة ربك » أي أن الله سبحانه علم من الأزل أن هؤلاء لا يؤمنون ، ولم يكن ذلك لأنه لم تتم الحجة عليهم ، بل لأنهم فسقوا ، وخرجوا من توحيد الله إلى الشرك. [35] ثم ذكر سبحانه حججا أخرى على التوحيد ونفي الشريك ( قُلْ ) يا رسول الله لهؤلاء المشركين : ( هَلْ مِنْ شُرَكائِكُمْ ) أي الذين جعلتموهم شركاء لله ، فإنهم لما كانوا مختلقين ، كانت نسبتهم إلى مخترعيهم أولى من نسبتهم إلى الله سبحانه ، فلم يقل تعالى « شركائي » مَنْ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُ قُلِ اللهُ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُ فَأَنَّى تُؤْفَكُونَ (34) قُلْ هَلْ مِنْ شُرَكائِكُمْ مَنْ يَهْدِي إِلَى الْحَقِّ قُلِ اللهُ يَهْدِي لِلْحَقِّ أَ فَمَنْ يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَنْ يُتَّبَعَ أَمَّنْ لا يَهِدِّي ( مَنْ يَبْدَؤُا الْخَلْقَ ) بالإيجاد ( ثُمَّ يُعِيدُهُ ) فانيا كما كان ، أو يعيده بعد الموت إلى الحياة. وحيث لا يحير هؤلاء جوابا ، إذ لا تفعل شركاؤهم ذلك ، ويفحمون بهذا الاحتجاج ( قُلْ ) يا رسول الله في الجواب : ( اللهُ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُ ) إن ذلك خاص به لا يتمكن أحد من هذا العمل سواه ( فَأَنَّى تُؤْفَكُونَ ) أي إلى أين تصرفون عن الحق ؟ من « أفك » بمعنى : انقلب وانصرف عن الحق.` },
            { text: "قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ فَأَنَّىٰ تُؤْفَكُونَ", tafsir: `` },
            { text: "قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ", tafsir: `يا رسول الله لهؤلاء المشركين : ( هَلْ مِنْ شُرَكائِكُمْ ) الأصنام التي جعلتموها شركاء كذبا وزورا ( مَنْ يَهْدِي إِلَى الْحَقِ ) أي إلى الرشد والصلاح كي يتنعم عبّادها بما فيه خيرهم وسعادتهم ، وحيث أنهم لا يتمكنون من الإجابة بالإثبات ، وإلا طولبوا بالدليل. ولا يخفى أن هذا الاحتجاج كان مع عبّاد الأصنام ، لا مع عبّاد المسيح عليه‌السلام ونحوهم ( قُلْ ) يا رسول الله في الجواب : ( اللهُ يَهْدِي لِلْحَقِ ) فإنه هو الذي أنزل الشرائع وأرسل الرسل لهداية الناس من الظلمات إلى النور ، وتعليم طرق الصلاح والرشاد والسعادة. ثم يتوجه هنا سؤال يدخل فيه جميع الآلهة حتى عيسى عليه‌السلام في زعم عبّاده ( أَ فَمَنْ يَهْدِي إِلَى الْحَقِ ) ويرشد إلى الطريق السوي ، وهو الله سبحانه ( أَحَقُّ أَنْ يُتَّبَعَ ) ويأخذ الإنسان بأوامره ونواهيه ( أَمَّنْ لا يَهِدِّي ) ؟ إِلاَّ أَنْ يُهْدى فَما لَكُمْ كَيْفَ تَحْكُمُونَ (35) وَما يَتَّبِعُ أَكْثَرُهُمْ إِلاَّ ظَنًّا إِنَّ الظَّنَّ لا يُغْنِي مِنَ الْحَقِّ شَيْئاً أصله « يهتدي » من باب « الانفعال » ، قلبت « التاء » « دالا » وأسقطت همزة الوصل من أوله ، لنقل حركة التاء إلى الهاء ، فصار « هدّى » « يهدّي » والمعنى : هل الله أحق بالاتباع أم من لا يهتدي ( إِلَّا أَنْ يُهْدى ) فمن يحتاج إلى الاهتداء لا يصلح أن يتخذ ربا ، فالمسيح عليه‌السلام وإن كان نبيا عظيما إلّا أنه ينطبق عليه هذا الوصف ، إذ لا يهتدي إلا بهداية الله سبحانه. أما الأصنام فهي أبعد ، إذ أنها جمادات لا تهتدي حتى إذا أرادوا هدايتها. وكأن القرآن جرى في هذا الاحتجاج مجرى المسلّم من خصمه ببعض مقدماته ليرد عليه حتى على ذلك الفرض ، والمشركون كانوا قد فرضوا عقلا للأصنام وأنها تشعر ( فَما لَكُمْ ) أيها المشركون ، والمعنى : ما هو سبب قولكم بغير الحق ، وأنتم تعلمون ( كَيْفَ تَحْكُمُونَ ) بأن هذه الأصنام آلهة بعد ما قامت الحجة على بطلانها.` },
            { text: "وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ", tafsir: `أي أن أكثر هؤلاء المشركين إنما يتبعون الظنون في اعتقادهم بألوهية الأصنام ، فإنهم لا يتيقنون بذلك جزما ، إنما رأوا آباءهم عبدوها ، فظنوا بصحتها تقليدا ، والحال ( إِنَّ الظَّنَّ لا يُغْنِي مِنَ الْحَقِّ شَيْئاً ) فإن الظن ترجيح أحد الطرفين ، وهذا ليس بواقع ولا معذّر ، أما أنه ليس بواقع ، فلأن الواقع لا يتبع أداء الأشخاص ، وأما أنه ليس بمعذّر فلأن العقلاء الملتفتين لا يعتمدون عليه في الأمور المهمة ، وهذا بخلاف القطع فإنه إن حصل من إِنَّ اللهَ عَلِيمٌ بِما يَفْعَلُونَ (36) وَما كانَ هذَا الْقُرْآنُ أَنْ يُفْتَرى مِنْ دُونِ اللهِ وَلكِنْ تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ وَتَفْصِيلَ الْكِتابِ مقدمات صحيحة كان مطابقا للواقع ومعذّرا ( إِنَّ اللهَ عَلِيمٌ بِما يَفْعَلُونَ ) فيجازيهم بأعمالهم الباطلة التابعة لظنون تقليدية واهية. [38] ثم ينتقل السياق إلى الكلام حول القرآن الذي كان معجزة الرسول صلى‌الله‌عليه‌وآله‌وسلم والدليل على صدقه وصحة كلامه ، ويستعرض مناقشاتهم حوله والجواب عنها ( وَما كانَ هذَا الْقُرْآنُ أَنْ يُفْتَرى ) أي يكون مفترى ( مِنْ دُونِ ) نزول من عند ( اللهِ ) سبحانه ، فلا يتمكن أحد أن يفتري قرآنا وينسبه إلى الله سبحانه ، فإن الكلام المفترى ليس كالقرآن ، لأن له أسلوبا خاصا معجزا ، وأنظمة وتشريعات لا يتمكن البشر من الإتيان بمثلها. بالإضافة إلى أن أحدا لو افترى على الله وجاء بمعجز ، كان حتما من الحكمة أن يكذبه الله سبحانه ، وإلا كان إغراء بالجهل ، وذلك قبيح على الله سبحانه. وقد دل التاريخ أن كل كاذب جاء بشيء ظاهره معجز ـ سحرا ـ لم يلبث أن انكشف سره وظهر كذبه. ( وَلكِنْ ) هو كتاب سماوي من عنده تعالى ، وكان ( تَصْدِيقَ الَّذِي بَيْنَ يَدَيْهِ ) أي مصدقا للكتب السابقة التي جاء بها الأنبياء عليهم‌السلام فهؤلاء المعارضون له غير مرتبطين بشرائع الله ، فهم بمعزل عن الدين إطلاقا ( وَتَفْصِيلَ الْكِتابِ ) أي أن القرآن تفصيل للذي كتبه سبحانه على البشر من الأحكام والشرائع ، كما قال سبحانه : ( كُتِبَ عَلَيْكُمُ الصِّيامُ ) (1) ، ( 1) البقرة : 184. لا رَيْبَ فِيهِ مِنْ رَبِّ الْعالَمِينَ (37) أَمْ يَقُولُونَ افْتَراهُ قُلْ فَأْتُوا بِسُورَةٍ مِثْلِهِ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللهِ ( لا رَيْبَ فِيهِ ) أي ليس في القرآن مجالا للريب ، إذ حججه ساطعة وأدلته واضحة ، فمن ارتاب فيه فقد ارتاب ارتيابا في غير موضعه ، كمن يرتاب في النهار ( مِنْ رَبِّ الْعالَمِينَ ) بدليل أنه معجز لا يقدر أحد من البشر من الإتيان بمثله.` },
            { text: "وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `أي أن الكفار بعد هذه الحجج يقولون أن الرسول صلى‌الله‌عليه‌وآله‌وسلم افترى القرآن ، ونسبه إلى الله من دون أن يكون منه ، و « أم » هنا بمعنى « بل » الإضرابية ، وفيه استفهام إنكاري ( قُلْ ) يا رسول الله لهم : ( فَأْتُوا بِسُورَةٍ مِثْلِهِ ) أي مثل القرآن في البلاغة والإعجاز ، فإن إعجاز القرآن من نواحي متعددة منها بلاغته الخارقة. وقد تحدّى القرآن بلغاء العالم بأن يأتوا بسورة واحدة مثل سور القرآن ولو كأقصر سورة نحو ( بِسْمِ اللهِ الرَّحْمنِ الرَّحِيمِ* قُلْ هُوَ اللهُ أَحَدٌ* اللهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ ) (1) لكنهم لم يتمكنوا. وقد كان تحدّي القرآن متدرجا ، فتحدّاهم أولا أن يأتوا بمثل تمام القرآن ، ثم بمثل عشر سور ، ثم بمثل سورة ، لكنهم لم يقدروا على أي منها ، وذلك دليل أنه معجز ، إذ لو لم يكن معجز لقدر البشر على الإتيان بمثله ، لأن مواده وهي الألفاظ والكلمات بل والجمل كانت تحت قدرتهم. ( وَادْعُوا مَنِ اسْتَطَعْتُمْ ) دعوته من الجن والإنس ( مِنْ دُونِ اللهِ ) ( 1) الإخلاص : 1 ـ 5. إِنْ كُنْتُمْ صادِقِينَ (38) بَلْ كَذَّبُوا بِما لَمْ يُحِيطُوا بِعِلْمِهِ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُ أي غير الله سبحانه ، ليشاركونكم وليساندوكم في الإتيان بسورة واحدة مثل القرآن ، أما الله فهو القادر على ذلك ، فاللازم أن يكون الطلب من سواه ( إِنْ كُنْتُمْ صادِقِينَ ) في أن القرآن من كلام البشر ، وليس من كلام الله سبحانه. [40] ثم بيّن سبحانه أن تكذيب هؤلاء بدون دليل وبرهان ( بَلْ كَذَّبُوا بِما لَمْ يُحِيطُوا بِعِلْمِهِ ) كذبوا بالقرآن قبل أن يطّلعوا على كنه أمره وحقيقته ، كالجاهل الذي يكذّب بالشيء بدون أن يقلّب أوجه الرأي فيه. إنهم حيث لم يألفوا الأنبياء والمعاجز وكانوا جاهلين بذلك تمام الجهل كذبوا بمجرد السماع والرؤية ، بدون أن يتدبروا في أنه لو كان كذبا مفترىّ لتمكنوا من الإتيان بمثله ، فإن الحكيم دائما يفكر ويتدبر ثم يحكم ويظهر النتيجة ، أما الجاهل فإنه يسرع في اتخاذ النتائج قبل التدبّر والتفكّر في المقدمات. ( وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُ ) أي لم يأتهم بعد ما يؤول إليه أمر الكتاب ، أي بدون أن يعرفوا مآل الكتاب ، وأنه كيف يكون وإلى ما ينتهي. وهذا كقولك : « فلان يسرع بتكذيبي بدون أن يتدبر كلامي وأن يرى مصير هذا الكلام » ، فإن كثيرا من الأشياء يعرف صدقها من كذبها من حال مصائرها ، فإذا قال زيد : « سيجيء الحاج إلى كربلاء » ، كان اللازم أن لا يكذبه السامع إلا إذا جاء وقت إخباره ولم يظهر منهم أثر ، أما أن يكذب بدون أن ينتظر أوله وآخره ، فهو خارج عن منطق العقلاء والمفكرين. كَذلِكَ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ فَانْظُرْ كَيْفَ كانَ عاقِبَةُ الظَّالِمِينَ (39) وَمِنْهُمْ مَنْ يُؤْمِنُ بِهِ وَمِنْهُمْ مَنْ لا يُؤْمِنُ بِهِ وَرَبُّكَ أَعْلَمُ بِالْمُفْسِدِينَ (40) وَإِنْ كَذَّبُوكَ فَقُلْ لِي عَمَلِي وَلَكُمْ عَمَلُكُمْ أَنْتُمْ بَرِيئُونَ مِمَّا أَعْمَلُ وَأَنَا بَرِيءٌ مِمَّا تَعْمَلُونَ (41) ( كَذلِكَ ) أي كتكذيب هؤلاء ( كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ ) من أمم الأنبياء بدون أن يفهموا كلامهم وينتظروا عواقب كلامهم ، هل يصدق إخبارهم عن المستقبل أم لا ( فَانْظُرْ ) يا رسول الله ( كَيْفَ كانَ عاقِبَةُ الظَّالِمِينَ ) الذين كذبوا الأنبياء ، فعاقبة هؤلاء كعاقبة أولئك ، فإن مصيرهم إلى الهلاك والعذاب. [41] وإذا كان غالب هؤلاء متّبعين للظن مكذّبين اعتباطا ، فإن منهم من يؤمن أيضا ، إذ الحق لا يخلو من أنصار ( وَمِنْهُمْ مَنْ يُؤْمِنُ بِهِ ) أي بالقرآن ، بترك كفرهم وشركهم ، واتباع الحق ( وَمِنْهُمْ مَنْ لا يُؤْمِنُ بِهِ ) بل يبقى في غيّه وضلاله ، ( وَرَبُّكَ ) يا رسول الله ( أَعْلَمُ بِالْمُفْسِدِينَ ) الذين يدومون على فسادهم ، فإن الكافر مفسد مهما كان نزيها ، فإن الكفر هو أعظم فساد في الأرض ، لأنه خرق لمنهاج الله سبحانه.` },
            { text: "بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ", tafsir: `` },
            { text: "وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ", tafsir: `يا رسول الله بعد إلزام الحجة ، وإتمام الدليل ( فَقُلْ ) لهم : ليعمل كلّ طرف منّا حسب منهجه ومعتقده ، فإني لا أحمل تبعة أعمالكم ، كما أنكم لا تنتفعون بعملي ( لِي عَمَلِي ) وسأرى جزاءه ( وَلَكُمْ عَمَلُكُمْ ) وسترون جزاءه ( أَنْتُمْ بَرِيئُونَ مِمَّا أَعْمَلُ ) أنا من الطاعة والعبادة ( وَأَنَا بَرِيءٌ مِمَّا تَعْمَلُونَ ) من المعاصي والكفران. وَمِنْهُمْ مَنْ يَسْتَمِعُونَ إِلَيْكَ أَ فَأَنْتَ تُسْمِعُ الصُّمَّ وَلَوْ كانُوا لا يَعْقِلُونَ (42) وَمِنْهُمْ مَنْ يَنْظُرُ إِلَيْكَ أَ فَأَنْتَ تَهْدِي الْعُمْيَ وَلَوْ كانُوا لا يُبْصِرُونَ (43) وهذا شبه وعيد لهم بأنهم وحدهم يلاقون جزاء أعمالهم الباطلة.` },
            { text: "وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ", tafsir: `أي من هؤلاء الكفار ( مَنْ يَسْتَمِعُونَ إِلَيْكَ ) بآذانهم ، لكنهم أغلقوا قلوبهم عن الانتفاع ، فهم متّخذون مكان المتفرج وإنما يستمعون فقط بدون قصد التعلم والعمل ( أَ فَأَنْتَ ) يا رسول الله ( تُسْمِعُ الصُّمَ ) جمع « أصم » بمعنى : من فقد حاسة السمع ، أي أنك لا تقدر على إسماع الحق لمن صمّت أذن قلبه ( وَلَوْ كانُوا لا يَعْقِلُونَ ) فإن الإنسان يقدر على إسماع من يريد الاتباع والتعقل ، أما غيره فليس ينجح فيه كل كلام.` },
            { text: "وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ", tafsir: `أي من هؤلاء الكفار ( مَنْ يَنْظُرُ إِلَيْكَ ) يا رسول الله ، حين إلقائك الحجج والأدلة ، والناظر لا بد وأن يبصر الحق في المنظور إليه ، فإن الحركات والسكنات تدل على ما في قلب المتكلم من الحرارة والصدق ، ولكنهم ينظرون للتفرّج لا لتفهّم الحق وتعلّم الواقع ( أَ فَأَنْتَ ) يا رسول الله ( تَهْدِي الْعُمْيَ ) جمع « أعمى » ، فإنهم والأعمى سواء ، فكما لا ينتفع الأعمى ببصره كذلك لا ينتفع هؤلاء بما يرون من الحق ( وَلَوْ كانُوا لا يُبْصِرُونَ ) فإن الإنسان يقدر على إراءة البصير ، أما الأعمى فإن الإنسان لا يقدر على إراءته الحق وإن اجتهد كل جهد. [45] وأخيرا ، إن كل ما يصيب هؤلاء إنما يصيبهم بسبب ظلمهم لأنفسهم ، إِنَّ اللهَ لا يَظْلِمُ النَّاسَ شَيْئاً وَلكِنَّ النَّاسَ أَنْفُسَهُمْ يَظْلِمُونَ (44) وَيَوْمَ يَحْشُرُهُمْ كَأَنْ لَمْ يَلْبَثُوا إِلاَّ ساعَةً مِنَ النَّهارِ يَتَعارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقاءِ اللهِ وَما كانُوا مُهْتَدِينَ (45) لأنهم لم ينتفعوا بكل ما أقيم لهم من الحجج ( إِنَّ اللهَ لا يَظْلِمُ النَّاسَ شَيْئاً ) أي ظلما ولو يسيرا ( وَلكِنَّ النَّاسَ أَنْفُسَهُمْ يَظْلِمُونَ ) بإعراضهم عن الحق بعد إتمام الحجة ووضوح المحجة. [46] ثم بمناسبة عدالة الجزاء وكون ظلمهم لا يعود إلّا على أنفسهم يأتي السياق ليبيّن أنهم في الحشر يكونون في أسوأ حال وكأن دنياهم قد مرت كساعة ، وقد بقيت التبعات الجسام عليهم ( وَ ) يكون حال هؤلاء الكفار ( يَوْمَ يَحْشُرُهُمْ ) يجمعهم الله سبحانه لموقف القيامة ، ( كَأَنْ لَمْ يَلْبَثُوا ) أي لم يبقوا في الدنيا ( إِلَّا ساعَةً مِنَ النَّهارِ ) فهم لا يرون إلّا بريقا من الدنيا ، وكأن عمر الدنيا كان ساعة فقط ، وهذا ليس بغريب ، فالإنسان يرى وهو في الدنيا ماضي عمره كساعة أو شبهها ( يَتَعارَفُونَ بَيْنَهُمْ ) هناك ، أي يعرّف بعضهم لبعض ( قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقاءِ اللهِ ) خسروا أنفسهم وأهليهم وأموالهم ، والمراد من « لقاء الله » لقاء جزائه ، تشبيها للمعقول بالمحسوس ( وَما كانُوا مُهْتَدِينَ ) للحق ، فإن عدم اهتدائهم هنا سبب خسارتهم هناك. [47] إن الكفار تكون عاقبتهم إلى خسارة ، وقد وعد الله رسوله خزي الكفار ونصرة المسلمين عليهم ، ثم بيّن أنه سواء رأى خزيهم أو مات قبل أن يرى ذلك ، فإنه سبحانه لا بد وأن يجازيهم على سوء صنيعهم وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنا مَرْجِعُهُمْ ثُمَّ اللهُ شَهِيدٌ عَلى ما يَفْعَلُونَ (46) وَلِكُلِّ أُمَّةٍ رَسُولٌ فَإِذا جاءَ رَسُولُهُمْ قُضِيَ بَيْنَهُمْ بِالْقِسْطِ وَهُمْ لا يُظْلَمُونَ (47) وكفرهم ، ( وَإِمَّا نُرِيَنَّكَ ) يا رسول الله « إن » شرطية و « ما » زائدة للتجميل ( بَعْضَ الَّذِي نَعِدُهُمْ ) بأن تكون في الحياة ، فترى بعض العقوبات التي ننزلها بالكفار كما وعدناهم بها ( أَوْ نَتَوَفَّيَنَّكَ ) نقبض روحك قبل أن ترى عقوبتنا لهم فإنهم لا يفوتوننا ، بل ( فَإِلَيْنا مَرْجِعُهُمْ ) أي رجوعهم فنريكه في الآخرة ( ثُمَ ) بعد رجوعهم لا يتمكنون أن يفروا من عقابه بالإنكار ، فإن ( اللهُ شَهِيدٌ عَلى ما يَفْعَلُونَ ) فيجازيهم حسب أعمالهم التي شهدها. [48] ثم بيّن القرآن الحكيم أن تعجّب هؤلاء الكفار من ادّعاء الرسول صلى‌الله‌عليه‌وآله‌وسلم للرسالة ليس في محله ، فإن الرسل قد أتت قبل الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى الأمم ( وَلِكُلِّ أُمَّةٍ رَسُولٌ ) « الأمة » الجماعة ، أي : لكل جماعة رسول يؤدي إليهم رسالة الله سبحانه ( فَإِذا جاءَ رَسُولُهُمْ ) بيّن لهم وأنذر وحذّر ، فإذا لم يقبلوا استحقوا العقاب ، على ما وعد سبحانه ( ( وَما كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً ) (1) ، ( قُضِيَ بَيْنَهُمْ بِالْقِسْطِ ) أي حكم الله سبحانه بينهم بالعدل ، فمن آمن أجزل له الأجر ، ومن لم يؤمن تمّت عليه الحجة واستحق العقاب ( وَهُمْ لا يُظْلَمُونَ ) لا ينقص من ثواب طاعاتهم ولا يزاد في عقاب سيئاتهم. [49] قد كان النبي صلى‌الله‌عليه‌وآله‌وسلم يعد المكذبين الهلاك والعقاب ، فكانوا يستعجلون ( 1) الإسراء : 16. وَيَقُولُونَ مَتى هذَا الْوَعْدُ إِنْ كُنْتُمْ صادِقِينَ (48) قُلْ لا أَمْلِكُ لِنَفْسِي ضَرًّا وَلا نَفْعاً إِلاَّ ما شاءَ اللهُ لِكُلِّ أُمَّةٍ أَجَلٌ إِذا جاءَ أَجَلُهُمْ فَلا يَسْتَأْخِرُونَ ساعَةً وَلا يَسْتَقْدِمُونَ (49) العقاب ، على طريقة الاستهزاء ( وَيَقُولُونَ ) أي يقول الكفار : ( مَتى هذَا الْوَعْدُ ) أي وعد عذاب الدنيا ، وعقاب الآخرة ( إِنْ كُنْتُمْ ) أيها المؤمنون القائلون بعذاب الكفار في الدنيا والآخرة ( صادِقِينَ ) فيما تقولونه.` },
            { text: "إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ", tafsir: `` },
            { text: "وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ", tafsir: `` },
            { text: "وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ", tafsir: `` },
            { text: "وَلِكُلِّ أُمَّةٍ رَّسُولٌ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ", tafsir: `` },
            { text: "وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `` },
            { text: "قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ لِكُلِّ أُمَّةٍ أَجَلٌ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ", tafsir: `يا رسول الله في جوابهم : إن أمر ضرري ونفعي ليس بيدي ، فكيف بأمر ضرركم ونفعكم ، إن ما نعدكم آت لكن وقته بيد الله سبحانه ( لا أَمْلِكُ لِنَفْسِي ضَرًّا وَلا نَفْعاً ) فلو شاء الله أن يضرّني لم أملك ردّه ، ولو أراد الله أن ينفعني لم أملك تغييره أو تعجيله ، ولو أردت نفعا لنفسي ولم يردّه الله لم أقدر عليه. وهذا واضح فإن الرسول لا يقدر على أمر لا يريده الله سبحانه ، وإنما يقدر على نفع نفسه وضرها ونفع الناس أو ضرها بأمر الله وإرادته. فالنفي هنا إضافي لا مطلق ، حتى ينافي ما دلّ على النفع الذي كان من الرسول صلى‌الله‌عليه‌وآله‌وسلم أو الضر الذي كان بسببه ، كما استثنى ذلك بقوله تعالى : ( إِلَّا ما شاءَ اللهُ ) أن يملكني أو يقدرني عليه ، وإذ لم أقدر على نفع نفسي وضرّها ، كيف أقدر لكم على ذلك. أما موعد عقابكم وحشركم فاعلموا أنه ( لِكُلِّ أُمَّةٍ أَجَلٌ ) ومدة لا بد أن يقضوها حتى تنزل بهم العقوبة على تكذيبهم وعصيانهم ( إِذا جاءَ أَجَلُهُمْ ) بأن سار إليهم ( فَلا يَسْتَأْخِرُونَ ) أجلهم أي لا يؤخرونه ، بمعنى عدم قدرتهم على ذلك ( ساعَةً ) جزءا من الزمان ( وَلا يَسْتَقْدِمُونَ ) لا يقدّمونه عن قُلْ أَ رَأَيْتُمْ إِنْ أَتاكُمْ عَذابُهُ بَياتاً أَوْ نَهاراً ما ذا يَسْتَعْجِلُ مِنْهُ الْمُجْرِمُونَ (50) أَ ثُمَّ إِذا ما وَقَعَ آمَنْتُمْ بِهِ آلْآنَ موعده ووقته ، فإذا كان وقت هلاكهم يوم الجمعة وسار الأجل نحوهم من يوم الأربعاء ، لا يتمكنون أن يؤخروه إلى يوم السبت ولا يتمكنون أن يجعلونه في يوم الخميس.` },
            { text: "قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ", tafsir: `يا رسول الله لهؤلاء المكذبين المستعجلين بالعذاب : ( أَ رَأَيْتُمْ ) أي أخبروني ، فإن « أ رأيت » تستعمل بمعنى : أخبرني ( إِنْ أَتاكُمْ عَذابُهُ ) أي عذاب الله ( بَياتاً ) أي ليلا ( أَوْ نَهاراً ) ما أنتم صانعون ؟ فقد حذف جواب « إن » لدلالة الكلام عليه ( ما ذا يَسْتَعْجِلُ مِنْهُ ) أي من العذاب ( الْمُجْرِمُونَ ) « ما » مبتدأ و « ذا » بمعنى « الذي » خبره ، والجملة استئنافية ، أي : ما الذي يستعجل المجرمون من العذاب ، والاستفهام معناه التهويل ، كما نقول لمن يفعل شيئا عاقبته سيئة : « ما الذي تجني على نفسك ؟ » فمفاد الآية : أنكم تستعجلون شيئا مهولا مهلكا.` },
            { text: "أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ءَآلْـَٰٔنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ", tafsir: `« الهمزة » للاستفهام ، و « ثم » للعطف ، أي : هل ـ بعد استعجالكم للعذاب ـ إذا وقع العذاب ، في ذلك الحين تؤمنون به. فقد كانوا لا يؤمنون بالعذاب ، وكانوا يستعجلونه على جهة الاستهزاء ، و « ما » زائدة جاءت للتزيين ، وقد ذكرنا سابقا أنه ـ غالبا ـ يأتي الكلام بصورة النفي ، ويراد منه الإثبات .. ثم كأن النفس انتقلت إلى جو وقع العذاب فيه ـ بعد ما كانت في الدنيا طرفا لخطاب الرسول ـ فيقال للمكذّبين حين يشاهدون العذاب ويريدون الإيمان للتخلّص منه ( آلْآنَ ) تؤمنون ، على نحو الاستفهام وَقَدْ كُنْتُمْ بِهِ تَسْتَعْجِلُونَ (51) ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا ذُوقُوا عَذابَ الْخُلْدِ هَلْ تُجْزَوْنَ إِلاَّ بِما كُنْتُمْ تَكْسِبُونَ (52) وَيَسْتَنْبِئُونَكَ أَ حَقٌّ هُوَ قُلْ إِي وَرَبِّي إِنَّهُ لَحَقٌّ وَما أَنْتُمْ بِمُعْجِزِينَ (53) الإنكاري ، أي أنه لا ينفعكم الإيمان الآن ( وَ ) الحال أنه ( قَدْ كُنْتُمْ بِهِ ) بالعذاب ( تَسْتَعْجِلُونَ ) فكنتم مكذبين له مستهزئين به ، أي أن الإيمان الآن في حين رؤية العذاب غير نافع بعد تكذيبكم له سابقا ، ونظيره ( ( آلْآنَ وَقَدْ عَصَيْتَ قَبْلُ ) (1) .` },
            { text: "ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ", tafsir: `بعد وقوع العذاب عليهم ، وعدم فائدة إيمانهم حين معاينة العذاب ( قِيلَ لِلَّذِينَ ظَلَمُوا ) بالكفر والعصيان واستعجال العذاب استهزاء : ( ذُوقُوا عَذابَ الْخُلْدِ ) أي العذاب الخالد الدائم في الآخرة بعد عذاب الدنيا ( هَلْ تُجْزَوْنَ إِلَّا بِما كُنْتُمْ تَكْسِبُونَ ) أي لا تجزون إلّا بما كسبتم في الدنيا ، فليس العذاب ظلما وإنما هو جزاء أعمالكم. [54] إن المكذبين لم يكونوا على علم في تكذيبهم ، بل كانوا مستبعدين للعذاب وسائر ما يخبر به النبي صلى‌الله‌عليه‌وآله‌وسلم ، ولذا كانوا يسألون عن حقيقة الأمر ( وَيَسْتَنْبِئُونَكَ ) يستخبرونك ويطلبون منك يا رسول الله أن تخبرهم ( أَ حَقٌّ هُوَ ) هل حق ما جئت به من الأحكام والوعد والوعيد وغيرهما ؟ ( قُلْ ) يا رسول الله في جوابهم : ( إِي ) إنه حق ( وَرَبِّي ) أي قسما بالله ( إِنَّهُ لَحَقٌ ) لا شك فيه ( وَما أَنْتُمْ بِمُعْجِزِينَ ) لا ( 1) يونس : 92. وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ ما فِي الْأَرْضِ لافْتَدَتْ بِهِ وَأَسَرُّوا النَّدامَةَ لَمَّا رَأَوُا الْعَذابَ وَقُضِيَ بَيْنَهُمْ بِالْقِسْطِ وَهُمْ لا يُظْلَمُونَ (54) تتمكنون من أن تعجزوا الله سبحانه فلا يتمكن من إنفاذ أمره ، أو على أن تعجزوه من تعذيبكم ، فقد كان الكفار يظنون أنهم قادرون على إطفاء نور الله ، والفرار من عقابه. [55] إن العذاب إذا جاء للمكذّب لا يتمكن من النجاة منه ، لا بنحو تعجيزه سبحانه بالقوة ، ولا بنحو الافتداء للخلاص منه ، وهو من الهول بحيث إن الإنسان حاضر لإعطاء جميع ما في الأرض للخلاص ، ولكن هيهات ! ( وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ ) بالشرك والكفر ، أو بالعصيان والطغيان ( ما فِي الْأَرْضِ ) من الثروة ( لَافْتَدَتْ بِهِ ) أعطت كل ما في الأرض فدية عن نفسها ليخلّصها من العذاب ، فإن عذاب الله هائل إلى هذا الحد ، حتى يستعد المجرم للتنازل عن جميع ما يملك ـ ولو كان كل ما في الأرض ـ لأجل أن لا يعذّب ، ولكن ليس للإنسان جميع ما في الأرض ، ولا ينفعه في الافتداء والخلاص لو ملكه ( وَأَسَرُّوا ) أسرّ المجرمون ( النَّدامَةَ لَمَّا رَأَوُا الْعَذابَ ) أنهم أخفوا ندمهم على ما فات منهم لما رأوا العذاب. ولعل سر إخفائهم لندمهم أن لا يشمت بهم. وقد روي ذلك عن الصادق عليه‌السلام (1) . ( وَقُضِيَ بَيْنَهُمْ بِالْقِسْطِ ) أي بالعدل فكان عقابهم بمقدار أعمالهم السيئة ( وَهُمْ لا يُظْلَمُونَ ) ، فيما يفعل بهم من العذاب لأنه ( 1) راجع مجمع البيان : ج 5 ص 198. أَلا إِنَّ لِلَّهِ ما فِي السَّماواتِ وَالْأَرْضِ أَلا إِنَّ وَعْدَ اللهِ حَقٌّ وَلكِنَّ أَكْثَرَهُمْ بمقدار أعمالهم. ولا يقال : كيف أن هذه الأعمال القليلة استحقوا بها العقاب الكثير ومع ذلك فهو عدل ؟ لأنه يقال : إن العقاب ليس بقدر حجم الجرم ومدته ، بل بقدر آثاره المعنوية ، كما أن من يسبّ الملك يقتل ، ومن يزني يرجم ، فإن الأعمال ليست بحجومها وإنما بقيمتها ، كما نرى المهندس يعطى لساعة قضاها في رسم خريطة عشرة دنانير ، بينما العامل لا يعطى ليوم كامل دينارا ، وقد لاقى الحر والبرد. أما دوام العذاب فهو لنيّاتهم السيئة التي أظهروها وهم باقون عليها ( ( وَلَوْ رُدُّوا لَعادُوا لِما نُهُوا عَنْهُ ) (1) . [56] إن الله سبحانه يتمكن من إنفاذ وعوده لأن له كل شيء ، كما أنه تعالى ينفذها لأن وعده لا خلف فيه ، فلا يظن الإنسان أنه يعصي والمهدّد غير قادر ، أو أنه لا يفي بوعده ، فلا يعاقب ( أَلا إِنَّ لِلَّهِ ما فِي السَّماواتِ وَالْأَرْضِ ) فهو المالك المطلق لكل شيء. والمراد هنا : الأعم من الظرف والمظروف ، كما تقول : « تحت سلطة الملك ما في البلاد » ، تريد البلاد وما فيها. وحيث أن له كل شيء فهو يقدر على إنفاذ وعده بالعقاب لمن كفر وتمرد ( أَلا إِنَّ وَعْدَ اللهِ حَقٌ ) لا خلف فيه. نعم دلّ الدليل على أن قسما من وعيده يمكن العفو عنه ( وَلكِنَّ أَكْثَرَهُمْ ) أي أكثر ( 1) الأنعام : 29. لا يَعْلَمُونَ (55) هُوَ يُحيِي وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ (56) يا أَيُّهَا النَّاسُ قَدْ جاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفاءٌ لِما فِي الصُّدُورِ الناس أو أكثر المجرمين ( لا يَعْلَمُونَ ) فينكرون أن يكون كل شيء لله سبحانه ، أو أنه يفي بما وعد ، كما كانوا يقولون : ( لَنْ تَمَسَّنَا النَّارُ إِلَّا أَيَّاماً مَعْدُودَةً ) (1) ، وإنما قال أكثرهم ، لا جماعة من الناس ـ حتى من المجرمين ـ يعلمون كل ذلك. [57] أما إذا قال بعض الناس : إنا إذا متنا بطل كل شيء ، ولا عقاب حين ذاك ، فليعلموا أن الله سبحانه ( هُوَ يُحيِي ) الأموات ( وَيُمِيتُ ) الأحياء ، فبيده الحياة والموت ( وَإِلَيْهِ تُرْجَعُونَ ) يوم القيامة ، أي إلى حسابه وجزائه ، فلا يظنوا أن لهم فرارا من حكمه « ولا يمكن الفرار من حكومتك » . [58] ويعقب السياق على ما تقدم من الوعد والوعيد نداء عاما إلى البشر ( يا أَيُّهَا النَّاسُ ) خطاب لجميع البشر ( قَدْ جاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ ) « الموعظة » بيان ما يجب أن يرغب فيه ، وما يلزم أن يحذر عنه ، والمراد بها الأحكام الإسلامية وما نزل من قبله سبحانه من القرآن الكريم وسائر ما بيّنه الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَشِفاءٌ لِما فِي الصُّدُورِ ) فإن الصدور كانت مليئة بالخرافة في العقيدة ، وبالأدران في الصفات ، وبالهموم والأحزان والقلق ، والقرآن بما له من المناهج والإرشادات يعوض مكان الخرافة حقائق ، ومكان الرذالة فضيلة ، ومكان الأحزان ( 1) البقرة : 81. وَهُدىً وَرَحْمَةٌ لِلْمُؤْمِنِينَ (57) قُلْ بِفَضْلِ اللهِ وَبِرَحْمَتِهِ فَبِذلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ (58) والقلق ، الفرح والطمأنينة ، فهو يشفي الصدور من أمراضها ( وَهُدىً ) أي دلالة وهداية إلى الحق ( وَرَحْمَةٌ لِلْمُؤْمِنِينَ ) أي ما يسبب لهم أن ي رحمهم‌الله بفضله. [59] فبهذا الفضل الذي تفضّل به سبحانه على عباده والذي يسبب لهم صلاح الدنيا والآخرة يلزم أن يفرح الناس ، لا بالمال والجاه والأهل ، فإنها أمور ما لم يوضع لها منهاج صحيح كانت وبالا على الإنسان وموجبة للهموم والأحزان ( قُلْ ) يا رسول الله للناس : ( بِفَضْلِ اللهِ ) الذي تفضّل عليهم بالهداية ( وَبِرَحْمَتِهِ ) التي رحم بها عباده ( فَبِذلِكَ ) بكل واحد منهما ( فَلْيَفْرَحُوا ) فإنهما هما اللذان ينظّمان الحياة السعيدة ، وينتهيان بالإنسان إلى سعادة الآخرة. وكأن إتيان « الفاء » مكرّرة لنكتة بلاغية ، هي لأجل أن يبقى في النفس مجال للتملّي من الفضل والرحمة ، ولذلك جيء بقوله « فبذلك » أيضا ، مع غناء الكلام عنه ، وهو بدل من « بفضل الله » ( هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ ) من الأهل والمال والجاه ، فإنها إلى نفاد وفناء وتوجب الوبال إن لم يقترن بها فضل الله ورحمته. وما ورد أن « فضل الله » هو الإمام المرتضى ، وكذلك في الآية السابقة من تفسير « هو » في « أحق هو » بالإمام عليه‌السلام ، فإن ذلك من باب المصداق الجلي ، أو أحد المصاديق ، كما هو كذلك في غالب الآيات المفسرة به وبآله الأطهار عليهم‌السلام ، وكان هذا وأشباهه من بطون القرآن السبعة أو السبعين. قُلْ أَ رَأَيْتُمْ ما أَنْزَلَ اللهُ لَكُمْ مِنْ رِزْقٍ فَجَعَلْتُمْ مِنْهُ حَراماً وَحَلالاً قُلْ آللهُ أَذِنَ لَكُمْ أَمْ عَلَى اللهِ تَفْتَرُونَ (59) [60] إن الله سبحانه تفضّل عليهم بكل شيء ، لكن الإنسان الجاهل جعل الكفر مكان الشكر ، فبدّل الأوهام مكان الحقائق في العقيدة ، كما جعل من رزق الله سبحانه الحلال حراما افتراء منه عليه سبحانه ، بلا دليل ولا برهان ( قُلْ ) يا رسول الله لهؤلاء الكفار الذين يحكمون حسب أهوائهم : ( أَ رَأَيْتُمْ ) أي أخبروني ( ما أَنْزَلَ اللهُ لَكُمْ مِنْ رِزْقٍ ) حلال كله ، والمراد ب « الإنزال » كونه من ناحيته سبحانه ، فله العلو المنزليّ ، فما يأتي منه كأنه ينزل من علو ، تشبيها للمعقول بالمحسوس كما قال : ( وَأَنْزَلْنَا الْحَدِيدَ ) (1) ، و ( ( اهْبِطُوا مِنْها ) (2) ، و ( أَنْزَلْنا إِلَيْكَ آياتٍ ) (3) ـ على احتمال في بعضها ـ أو المراد بإنزاله : إنزال بعض أجزائه الذي هو المطر والشعاع فلولاهما لم يكن رزق ( فَجَعَلْتُمْ مِنْهُ ) أي من ذلك الرزق ( حَراماً وَحَلالاً ) بينما كان كله حلالا ، فقد كانوا يرمون السائبة والبحيرة والحام وأقسام أخرى من المأكولات ( قُلْ آللهُ أَذِنَ لَكُمْ ) أصله « أألله » بهمزتين ، همزة الاستفهام ، وهمزة « أل » الداخلة على « إله » ثم قلبت إحداهما وجعلت هكذا بالمد. قال ابن مالك : مدّا في الاستفهام أو يسهل. أي : هل إن الله أذن لكم في تحريم بعض ما أنزل إليكم من الرزق ( أَمْ عَلَى اللهِ تَفْتَرُونَ ) في أن تنسبوا إليه تحريم ما لم يحرمه افتراء وكذبا. ( 1) الحديد : 26. ( 2) البقرة : 39. ( 3) البقرة : 100. وَما ظَنُّ الَّذِينَ يَفْتَرُونَ عَلَى اللهِ الْكَذِبَ يَوْمَ الْقِيامَةِ إِنَّ اللهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلكِنَّ أَكْثَرَهُمْ لا يَشْكُرُونَ (60) وَما تَكُونُ فِي شَأْنٍ وَما تَتْلُوا مِنْهُ مِنْ قُرْآنٍ وَلا تَعْمَلُونَ مِنْ عَمَلٍ إِلاَّ كُنَّا عَلَيْكُمْ شُهُوداً` },
            { text: "وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ وَمَآ أَنتُم بِمُعْجِزِينَ", tafsir: `` },
            { text: "وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ", tafsir: `` },
            { text: "أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ", tafsir: `` },
            { text: "قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ", tafsir: `` },
            { text: "قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ", tafsir: `` },
            { text: "وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ", tafsir: `كهؤلاء الذين افتروا عليه تحريم بعض الرزق ( يَوْمَ الْقِيامَةِ ) أي عند لقائه سبحانه ؟ ما يظنون أن يفعل بهم ؟ إنه تهديد لهم ، فإن المفتري لا بد وأن تكون له عاقبة سيئة وقت الجزاء ، والمعنى : أ يحسبون أنهم لا يجازون على افترائهم ؟ ( إِنَّ اللهَ لَذُو فَضْلٍ عَلَى النَّاسِ ) حيث أحلّ لهم الأرزاق بعد أن منحهم إياها ( وَلكِنَّ أَكْثَرَهُمْ لا يَشْكُرُونَ ) فيحرّمون ما أحلّه افتراء عليه ، عوض أن يشكروه حيث أنعم وحلّل. [62] إنهم يفترون على الله الكذب في تحريمهم ما أحلّ الله سبحانه ، والله شاهد على كل عمل لا يعزب عنه مثقال ذرة ، فهل يغني افتراؤهم عليه ؟ ( وَما تَكُونُ ) أنت يا رسول الله ( فِي شَأْنٍ ) من شؤون الدنيا أو الآخرة ، من عمل أو عبادة أو غيرهما ـ والخطاب وإن كان للرسول صلى‌الله‌عليه‌وآله‌وسلم ، إلا أنه ليس خاصا به بل عام لكل أحد ـ ( وَما تَتْلُوا مِنْهُ ) أي من الشأن ( مِنْ قُرْآنٍ ) فإنه من تلك الشؤون التي هي للإنسان قسم هو شأن تلاوة القرآن ، كما أن من تلك الشؤون شأن الصلاة ، وشأن الكسب وغيرهما. وخصّت قراءة القرآن لأهميتها ( وَلا تَعْمَلُونَ ) أيها البشر ( مِنْ عَمَلٍ ) صغيرا كان أو كبيرا ( إِلَّا كُنَّا عَلَيْكُمْ شُهُوداً ) نشهده ونعلمه. والإتيان بضمير الجمع للتعظيم ، فقد جرت إِذْ تُفِيضُونَ فِيهِ وَما يَعْزُبُ عَنْ رَبِّكَ مِنْ مِثْقالِ ذَرَّةٍ فِي الْأَرْضِ وَلا فِي السَّماءِ وَلا أَصْغَرَ مِنْ ذلِكَ وَلا أَكْبَرَ إِلاَّ فِي كِتابٍ مُبِينٍ (61) العادة أن الكبراء يتكلمون عن أنفسهم وعن أتباعهم ( إِذْ تُفِيضُونَ فِيهِ ) تدخلون في ذلك العمل وتبتدئون به ، فشهادتنا مقترنة بأول كل أمر لا يفوت منا شيء من أوله ، والإفاضة غالبا تستعمل فيما يكون العمل سريعا ، ولكن النكتة في الإتيان بهذا اللفظ : أن الأعمال السريعة غالبا تفوت على الشاهد ، لكن الله سبحانه لا يغيب عنه شيء ولو كان العامل مسرعا في عمله. ( وَما يَعْزُبُ عَنْ رَبِّكَ ) أي لا يغيب عنه ( مِنْ مِثْقالِ ذَرَّةٍ ) أي ما هو بثقل الذرة وهي الهباءة الصغيرة التي تسبح في الفضاء وترى إذا دخلت أشعة الشمس المكان المظلم من كوّة ونحوها ، و « من » زائدة تأتي لبيان التعميم المستفاد من « ما » النافية قبلها ، سواء كانت تلك الذرة ( فِي الْأَرْضِ وَلا فِي السَّماءِ ) . ولعلّ ذكر « مثقال » لبيان أن الله كما يعلم نفس الذرة يعلم ثقلها ، وهو أدق من العلم بأصلها كثيرا ، فإن العلم بأصل الذرة يحصل للناس كثيرا ، أما العلم بوزنها فلا يحصل للناس إلا نادرا جدا ( وَلا أَصْغَرَ مِنْ ذلِكَ ) من مثقال ذرة ، أي : أيّ شيء كان أصغر من الذرة ، أو وزنه أقل من وزن الذرة ( وَلا أَكْبَرَ ) من ذلك ( إِلَّا فِي كِتابٍ مُبِينٍ ) كتاب واضح لديه سبحانه ، فإن علم كل ذلك في كتاب كتبه قبل أن يخلق الخلق ، وهو اللوح المحفوظ أو غيره ، وقوله : « لا أصغر » استئناف ، خبره « إلّا في كتاب مبين » . أَلا إِنَّ أَوْلِياءَ اللهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (62) الَّذِينَ آمَنُوا [63] إن هذه الدقة في الحساب والعلم توجب دهشة الإنسان وخوفه الشديد من القيامة ولقاء الله سبحانه ، لكن القرآن الحكيم يدرك هذا الأمر بقوله : ( أَلا إِنَّ أَوْلِياءَ اللهِ ) الذين هم أحباؤه ، يأتمرون بأوامره وينتهون عن زواجره ( لا خَوْفٌ عَلَيْهِمْ ) يوم القيامة من العقاب ( وَلا هُمْ يَحْزَنُونَ ) والفرق بين الخوف والحزن : أن الأول بالنسبة إلى الأمر المترقّب المحتمل صعوبته ، والثاني بالنسبة إلى المتقين ، صعوبة الأمر ، سواء كان ماضيا أو مستقبلا ، يقال : « إني على فقد ابني الذي فقدته لمحزون » ، ولا يقال : « لخائف » ، وهكذا لا يقال « إني لمحزون » من احتمال فقده ، ويقال : « إني لخائف منه » . أما بالنسبة إلى المتقين في المستقبل ، فإنه يستعمل الخوف والحزن معا بمعنى واحد ، فمن علم أنه سيدركه مخوف يقول : « إني خائف محزون » ، قال يعقوب عليه‌السلام : ( إِنِّي لَيَحْزُنُنِي أَنْ تَذْهَبُوا بِهِ وَأَخافُ أَنْ يَأْكُلَهُ الذِّئْبُ ) (1) . ثم إن المحتمل أن يكون المراد من جملة : ( لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) إنشائية ، بأن تكون نهيا عن الخوف والحزن. ويحتمل أن تكون إخبارية ، أي : أنهم لا يخافون ولا يحزنون ، إما في الآخرة ، أو الأعم. وعدم خوفهم وحزنهم في الدنيا إضافي ، يعني أن الخوف والحزن الناشئين عن المعصية لا يكونان بالنسبة إليهم ، وإن كان هناك لهم خوف وحزن من نوع آخر. [64] ثم بيّن سبحانه ذلك بقوله : ( الَّذِينَ آمَنُوا ) بأن صحّت عقيدتهم ( 1) يوسف : 14. وَكانُوا يَتَّقُونَ (63) لَهُمُ الْبُشْرى فِي الْحَياةِ الدُّنْيا وَفِي الْآخِرَةِ لا تَبْدِيلَ لِكَلِماتِ اللهِ ذلِكَ هُوَ الْفَوْزُ الْعَظِيمُ (64) وَلا يَحْزُنْكَ قَوْلُهُمْ إِنَّ الْعِزَّةَ لِلَّهِ جَمِيعاً هُوَ السَّمِيعُ الْعَلِيمُ (65) ( وَكانُوا يَتَّقُونَ ) المعاصي فصحّت أعمالهم.` },
            { text: "وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍ مُّبِينٍ", tafsir: `` },
            { text: "أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `` },
            { text: "ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ", tafsir: `` },
            { text: "لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ لَا تَبْدِيلَ لِكَلِمَٰتِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `فإن مثل هذا الإنسان مطمئن القلب هادئ البال بينما يقلق العاصي والكافر ( وَفِي الْآخِرَةِ ) فإنه يبشر بنجاة النعيم ورضوان من الله. هذا بالإضافة إلى أن المؤمن المتقي لا تهمّه الكوارث والنوائب حيث يطمئن بثواب الله والجزاء ، فهو دائم البشارة وإن حزن قلبه ودمعت عيناه ، كمن رضّ بعض جسمه وأعطى بدله عشرة آلاف دينار ، فإنه وإن تألم لكنه مستبشر بالجزاء. وهكذا المتقون في الدنيا ، ومن مصاديق البشارة في الدنيا ، ما يبشّرهم به الملائكة عند موتهم ـ كما ورد في الأحاديث ـ. ( لا تَبْدِيلَ لِكَلِماتِ اللهِ ) فإن ما قرّره سبحانه من الجزاء والثواب للمتقين لا خلف فيه ولا تبديل ( ذلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ) الذي لا فوز فوقه ، والفلاح الذي لا فلاح مثله ، بشارة في الحياة الدنيا وفي الآخرة ، واطمئنان وهدوء فيهما ، وهل فوق ذلك نجاح أو فوز؟` },
            { text: "وَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `حيث أن أولياءه لا يحزنون ف ( لا يَحْزُنْكَ ) يا رسول الله ( قَوْلُهُمْ ) أي قول الكفار فيك وإيذائهم لك ، وإيقاعهم في المؤمنين بك ( إِنَّ الْعِزَّةَ لِلَّهِ جَمِيعاً ) فيمنعهم منك بعزّته ، ويعزّك وينصرك عليهم ( هُوَ السَّمِيعُ ) لأقوالهم ( الْعَلِيمُ ) بأعمالهم ، فيجازيهم أَلا إِنَّ لِلَّهِ مَنْ فِي السَّماواتِ وَمَنْ فِي الْأَرْضِ وَما يَتَّبِعُ الَّذِينَ يَدْعُونَ مِنْ دُونِ اللهِ شُرَكاءَ عليها ، وينقذك منهم. [67] وكيف لا تكون العزة لله جميعا والحال أن جميع الأشياء مما يعقل وما لا يعقل لله لا شريك له ( أَلا ) فلينتبه الإنسان ( إِنَّ لِلَّهِ ) ملكه وطوع إرادته ( مَنْ فِي السَّماواتِ وَمَنْ فِي الْأَرْضِ ) من ملك وأنس وجن ، وإذا كان العقلاء له ، فغيرهم من غير العاقل أولى بأن يكون ملكا له وخصّ العقلاء بالذكر بلفظ « من » دلالة على العظمة ، فإن من يملك العقلاء ، له العزة التي لا عزّة فوقها. ( وَما يَتَّبِعُ الَّذِينَ يَدْعُونَ مِنْ دُونِ اللهِ شُرَكاءَ ) أي أنه سبحانه يملك آلهة هؤلاء المشركين فهو عطف على « من » وجيء ب « ما » لأن غالب الآلهة هي أصنام لا تعقل ولا تدرك. وهنا احتمالان آخران : الأول : أن يكون المعنى : أن ما يعبده هؤلاء من دون الله ليس شركاء لله ، فإنها ليست آلهة حتى تكون شركاء حقيقيون وإن سموها شركاء. الثاني : أن يكون المعنى : أي شيء يتبع هؤلاء شركاء ؟ تقبيحا لفعلهم. ف « ما » على الأول موصولة ، وعلى الثاني نافية. وعلى الثالث استفهامية. ثم بيّن سبحانه أن عبّاد هذه الأصنام ليسوا على يقين في كونها إِنْ يَتَّبِعُونَ إِلاَّ الظَّنَّ وَإِنْ هُمْ إِلاَّ يَخْرُصُونَ (66) هُوَ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهارَ مُبْصِراً إِنَّ فِي ذلِكَ لَآياتٍ لِقَوْمٍ يَسْمَعُونَ (67) قالُوا اتَّخَذَ اللهُ وَلَداً سُبْحانَهُ هُوَ الْغَنِيُّ لَهُ ما فِي السَّماواتِ وَما فِي آلهة ( إِنْ يَتَّبِعُونَ ) أي ما يتبع هؤلاء المشركين ( إِلَّا الظَّنَ ) الحاصل لهم بالتقليد والعادة ( وَإِنْ هُمْ ) أي ما هم ( إِلَّا يَخْرُصُونَ ) يحدسون حدسا بلا علم ولا يقين. [68] إن الله سبحانه هو مالك من في السماوات ومن في الأرض ، ومالك الأصنام ، كما أنه هو الذي جعل الأنظمة الكونية ، التي لا تزال تتكرّر على الناس كل يوم ، بكل جمال وإتقان ( هُوَ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ ) أي لسكونكم عن أتعاب النهار ( وَالنَّهارَ مُبْصِراً ) أي جعل النهار مضيئا تهتدون بسببه إلى حوائجكم ( إِنَّ فِي ذلِكَ ) الجعل ( لَآياتٍ ) حجج ( لِقَوْمٍ يَسْمَعُونَ ) سماع تفهّم وتعقّل ، أما من لا يسمع ولا يصغي إلى الحق ، فإن تلك الآيات لا تفيده. [69] وحيث بيّن سبحانه عقيدة المشركين وزيف عقيدتهم وبيّن الأدلة على بطلانها ، عطف الكلام حول عقيدة أخرى غزت الأدمغة كثيرا ، وهي عقيدة اليهود والنصارى وبعض آخر ، من أن الله له ولد ( قالُوا ) قال الكفار : ( اتَّخَذَ اللهُ وَلَداً ) قال أهل الكتاب بأن عزير والمسيح أبناء الله ، وقال الكفار بأن الملائكة بنات الله ( سُبْحانَهُ ) أسبّحه تسبيحا ، وأنزّهه تنزيها من هذه الكذبة ( هُوَ الْغَنِيُ ) فلا حاجة له إلى اتخاذ الولد ، ولو على نحو التبنّي ( لَهُ ) تعالى ( ما فِي السَّماواتِ وَما فِي الْأَرْضِ إِنْ عِنْدَكُمْ مِنْ سُلْطانٍ بِهذا أَ تَقُولُونَ عَلَى اللهِ ما لا تَعْلَمُونَ (68) قُلْ إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللهِ الْكَذِبَ لا يُفْلِحُونَ (69) مَتاعٌ فِي الدُّنْيا ثُمَّ إِلَيْنا الْأَرْضِ ) فمن يملك كل شيء لا يمكن أن يكون له ولد ، إن الولد جزء الوالد فلا يكون مملوكا له ( إِنْ عِنْدَكُمْ مِنْ سُلْطانٍ بِهذا ) أي ما عندكم دليل يدل على هذا الاعتقاد وأنه سبحانه اتخذ الولد ( أَ تَقُولُونَ عَلَى اللهِ ما لا تَعْلَمُونَ ) فتنسبون إليه أمرا بدون علم ويقين ، فإنهم لم يكونوا على علم بأن له ولدا. وهذا استفهام توبيخي.` },
            { text: "أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ", tafsir: `` },
            { text: "قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ هُوَ ٱلْغَنِىُّ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ إِنْ عِندَكُم مِّن سُلْطَٰنٍۭ بِهَٰذَآ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `` },
            { text: "قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ", tafsir: `يا رسول الله لهؤلاء : ( إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللهِ الْكَذِبَ ) بأن ينسبون إليه أنه اتخذ شريكا أو اتخذ ولدا ( لا يُفْلِحُونَ ) أي لا يفوزون بالنجاة والسعادة لا في الدنيا ولا في الآخرة ، وقال في آية أخرى : ( وَيُنْذِرَ الَّذِينَ قالُوا اتَّخَذَ اللهُ وَلَداً ) (1) . وقد دل التاريخ على صحة ذلك الإخبار ، فقد وقعت في العالم المسيحي والعالم اليهودي على طول الخط مجازر مدهشة ، فهم من عصر ظلامهم إلى عصر نورهم ـ هذا القرن ـ في حروب طاحنة عجيبة لا تبقي ولا تذر ، وألوف القصص شاهدة على ذلك ، منها ما ذكره « سلامة موسى » في كتابه « حرية الفكر » : أن حربا وقعت بين قسمي المسيحيين ـ الكاثوليك والبروتستانت ـ وذهب ضحيتها أربعة عشر مليون من البشر ، في ألمانيا وحدها. [71] لهم ( مَتاعٌ ) قليل ( فِي الدُّنْيا ) يتمتعون أياما قلائل ( ثُمَّ إِلَيْنا ( 1) الكهف : 5. مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ الْعَذابَ الشَّدِيدَ بِما كانُوا يَكْفُرُونَ (70) وَاتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قالَ لِقَوْمِهِ يا قَوْمِ إِنْ كانَ كَبُرَ عَلَيْكُمْ مَقامِي وَتَذْكِيرِي بِآياتِ اللهِ فَعَلَى اللهِ تَوَكَّلْتُ مَرْجِعُهُمْ ) رجوعهم ، أي إلى حكمنا وجزائنا يكون مصيرهم ( ثُمَّ نُذِيقُهُمُ الْعَذابَ الشَّدِيدَ ) الدائم ( بِما كانُوا يَكْفُرُونَ ) بسبب كفرهم. [72] لقد سبقت الإشارة في هذه السورة إلى الأمم السابقة وأنهم لما كذبوا الرسل ذاقوا وبال أمرهم ( ( وَلَقَدْ أَهْلَكْنَا الْقُرُونَ مِنْ قَبْلِكُمْ لَمَّا ظَلَمُوا وَجاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّناتِ ) (1) ، وسبقت الإشارة إلى أن لكل أمة رسول ( ( وَلِكُلِّ أُمَّةٍ رَسُولٌ فَإِذا جاءَ رَسُولُهُمْ قُضِيَ بَيْنَهُمْ بِالْقِسْطِ وَهُمْ لا يُظْلَمُونَ ) (2) . وهنا يأتي البيان ليبين بعض تلك القصص اعتبارا وتذكرة ( وَاتْلُ ) أي قص يا رسول الله ( عَلَيْهِمْ ) على هؤلاء الكفار ( نَبَأَ نُوحٍ ) أي خبر نوح النبي عليه‌السلام ( إِذْ قالَ لِقَوْمِهِ يا قَوْمِ إِنْ كانَ كَبُرَ عَلَيْكُمْ ) شقّ وصعب عليكم ( مَقامِي ) إقامتي بين أظهركم فاستثقلتموني ( وَتَذْكِيرِي ) وعظي وتبييني لكم ( بِآياتِ اللهِ ) حججه ودلائله الدالة على وجوده وصفاته وسائر ما يرتبط به من النبوة والمعاد ( فَعَلَى اللهِ تَوَكَّلْتُ ) في زجركم وما تنوون إيقاعه علي ، فإني متوكل على الله في جميع أحوالي ، وأتوكل عليه في هذه الخصوصية أيضا. فلا يقال : مفهوم الشرط : عدم توكلّه في صورة عدم الشرط ؟ ( 1) يونس : 14. ( 2) يونس : 48. فَأَجْمِعُوا أَمْرَكُمْ وَشُرَكاءَكُمْ ثُمَّ لا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ اقْضُوا إِلَيَّ وَلا تُنْظِرُونِ (71) فَإِنْ تَوَلَّيْتُمْ فَما سَأَلْتُكُمْ مِنْ أَجْرٍ الجواب : إن القضية سالبة حينئذ بانتفاء الموضوع. أي أنه إن لم يكبر مقام نوح عندهم لم يكن خوف منهم حتى يتوكل عليه‌السلام ، على الله سبحانه للتوقي من خوفهم. ( فَأَجْمِعُوا ) أيها الكفار ( أَمْرَكُمْ ) حولي ( وَشُرَكاءَكُمْ ) أي تعاونوا مع الذين اتخذتموهم شركاء لله سبحانه ، واعزموا على أمر واحد ( ثُمَّ لا يَكُنْ أَمْرُكُمْ ) لإيذائي ( عَلَيْكُمْ غُمَّةً ) غمّا وحزنا ، بأن تتردّدوا فيه ، ويكون لكم وجه الخلاص مني ( ثُمَّ اقْضُوا إِلَيَ ) انهضوا لتنفذوا تدبيركم علي ( وَلا تُنْظِرُونِ ) لا تمهلونني حتى أفكر ، وحتى أجمع قراري لمقابلتكم. قال نوح عليه‌السلام هذا لهم على وجه التحدّي وبيان أنهم لا يتمكنون من القضاء عليه وإن جمعوا كل قواهم وتشاوروا فيما بينهم واتحدت كلمتهم وأسرعوا في تنفيذ كيدهم نحوه ، فإنه مستعصم بالله ومستنصر به ، وجميع القوى لا تتمكن أن توصل إليه سوء. وهذا أدل دليل على وجوده سبحانه ، وإلا لتمكن أولئك الكفرة من القضاء عليه. وهذا كما تقول أقوى الدول لأضعف الحكومات : « افعلوا ما شئتم واجمعوا أمركم وأسرعوا في تنفيذ خططكم فإنكم لا تتمكنون من شيء » .` },
            { text: "مَتَٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ", tafsir: `` },
            { text: "وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ", tafsir: `` },
            { text: "فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ", tafsir: `أي أعرضتم عن الحجج والآيات ولم تقبلوا نصحي وتذكيري ، فأنتم وشأنكم ، إن تولّيكم لا ينقص أجري وثوابي ( فَما سَأَلْتُكُمْ مِنْ أَجْرٍ ) حتى ينقص بإعراضكم ، كالمعلم الذي إذا أعرض إِنْ أَجْرِيَ إِلاَّ عَلَى اللهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ (72) فَكَذَّبُوهُ فَنَجَّيْناهُ وَمَنْ مَعَهُ فِي الْفُلْكِ وَجَعَلْناهُمْ خَلائِفَ وَأَغْرَقْنَا الَّذِينَ كَذَّبُوا بِآياتِنا فَانْظُرْ كَيْفَ كانَ عاقِبَةُ الْمُنْذَرِينَ (73) ثُمَّ بَعَثْنا مِنْ بَعْدِهِ رُسُلاً إِلى قَوْمِهِمْ التلاميذ عنه نقص أجره. والحاصل : إن أعرضتم عن قبول قولي لم يضرّني لأني لم أطمع في مالكم حتى يفوتني المال بتولّيكم عني ، بل يعود ضرر تولّيكم عليكم ( إِنْ أَجْرِيَ ) أي : ما أجري ( إِلَّا عَلَى اللهِ ) سبحانه ( وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ ) الذين يسلمون أمورهم إلى الله سبحانه ، فإني ماض في رسالتي ، مصمم على تبليغي ، وإن توليتم وأعرضتم.` },
            { text: "فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ", tafsir: `فكذّب أولئك الكفار نوحا عليه‌السلام ، وقالوا : أنت لست بنبي وأنكروا المبدأ والمعاد ( فَنَجَّيْناهُ وَمَنْ مَعَهُ ) من المؤمنين ( فِي الْفُلْكِ ) أي في السفينة ( وَجَعَلْناهُمْ ) جعلنا نوحا عليه‌السلام والمؤمنين معه ( خَلائِفَ ) خلفاء في الأرض بعد أولئك الكفار الذين أغرقوا ( وَأَغْرَقْنَا الَّذِينَ كَذَّبُوا بِآياتِنا ) فقد أمطرت السماء وتفجّرت العيون حتى أخذ الماء كل ما في الأرض ، وهناك هلك الكفار أجمع ( فَانْظُرْ ) يا رسول الله ـ والخطاب لكل من يصح منه النظر ـ والمراد ب « النظر » العلم ( كَيْفَ كانَ عاقِبَةُ الْمُنْذَرِينَ ) الذين أنذروا ولم ينفع فيهم الإنذار. وقومك هؤلاء يا رسول الله مثل أولئك ، إن كذبوا وأرادوا القضاء عليك نصرناك عليهم وأهلكناهم.` },
            { text: "ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ", tafsir: `أرسلنا ( مِنْ بَعْدِهِ ) بعد نوح عليه‌السلام ( رُسُلاً إِلى قَوْمِهِمْ ) فَجاؤُهُمْ بِالْبَيِّناتِ فَما كانُوا لِيُؤْمِنُوا بِما كَذَّبُوا بِهِ مِنْ قَبْلُ كَذلِكَ نَطْبَعُ عَلى قُلُوبِ الْمُعْتَدِينَ (74) ثُمَّ بَعَثْنا مِنْ بَعْدِهِمْ مُوسى وَهارُونَ إِلى فِرْعَوْنَ وَمَلائِهِ بِآياتِنا فَاسْتَكْبَرُوا وَكانُوا قَوْماً مُجْرِمِينَ (75) كإبراهيم وهود وصالح ولوط وشعيب عليهم‌السلام وغيرهم ( فَجاؤُهُمْ بِالْبَيِّناتِ ) بالحجج الواضحة والأدلة على المبدأ والمعاد والتكاليف ( فَما كانُوا لِيُؤْمِنُوا بِما كَذَّبُوا بِهِ مِنْ قَبْلُ ) فقد كانت تلك الأقوام مثل أسلافهم لا يؤمنون بالحق الذي كذبت الأسلاف به ، فإن المكذبين لهم طبيعة واحدة ، ومن قبيل موحّد ، كما أن المؤمنين من قبيل واحد ، ولذا صح نسبة ما للأسلاف إلى الأخلاف ، كما نسب سبحانه ما صدر من أسلاف اليهود إلى أخلافهم الذين كانوا في زمن نبي الإسلام صلى‌الله‌عليه‌وآله‌وسلم ( كَذلِكَ نَطْبَعُ عَلى قُلُوبِ الْمُعْتَدِينَ ) إن طبعنا على قلوب الذين يعتدون ويتجاوزون الحق ، إنما هو بعد ما أغلقوا هم قلوبهم عن قبول الحق ، واعتدوا عن سنن الحق.` },
            { text: "ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ", tafsir: `أي أرسلنا ( مِنْ بَعْدِهِمْ ) بعد أولئك الأمم والرسل ( مُوسى وَهارُونَ ) أخا موسى عليهما‌السلام ( إِلى فِرْعَوْنَ وَمَلَائِهِ ) أشراف قومه أو كلّهم ، فإن « الملأ » اسم للأشراف ، لأنهم يملئون القلوب هيبة ، والأنظار زينة ونظارة ( بِآياتِنا ) أي أرسلناهما مع أدلتنا الدالة على صدق دعواهما من المعجزات والخوارق ( فَاسْتَكْبَرُوا ) عن الانقياد لها والإيمان بها ( وَكانُوا قَوْماً مُجْرِمِينَ ) قد أجرموا وارتكبوا الآثام والمعاصي. فَلَمَّا جاءَهُمُ الْحَقُّ مِنْ عِنْدِنا قالُوا إِنَّ هذا لَسِحْرٌ مُبِينٌ (76) قالَ مُوسى أَ تَقُولُونَ لِلْحَقِّ لَمَّا جاءَكُمْ أَ سِحْرٌ هذا وَلا يُفْلِحُ السَّاحِرُونَ (77) قالُوا أَ جِئْتَنا لِتَلْفِتَنا عَمَّا وَجَدْنا عَلَيْهِ آباءَنا وَتَكُونَ لَكُمَا` },
            { text: "فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَٰذَا لَسِحْرٌ مُّبِينٌ", tafsir: `جاء فرعون وقومه المطالب الحقة التي كانت ( مِنْ عِنْدِنا قالُوا إِنَّ هذا ) الذي جئتما به من الخوارق والمعجزات ( لَسِحْرٌ مُبِينٌ ) سحر واضح ، لا حقيقة له وإنما هو شيء يجعلنا نتخيل الأمور على غير واقعها.` },
            { text: "قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ", tafsir: `عليه‌السلام لهم : ( أَ تَقُولُونَ لِلْحَقِّ لَمَّا جاءَكُمْ ) سحر ؟ وقد حذف محكي القول لدلالة الكلام عليه ، وذلك لنكتة أدبية هي أن تبقى النفس منتظرة فتذهب كل مذهب ، تعظيما لتشنيع القائل ، أو المراد من « أ تقولون » : أ تعيبون وتطعنون في الحق ؟ ( أَ سِحْرٌ هذا ) هل هذا الذي جئت به من الخوارق سحر ؟ وكم من فرق بين السحر والمعجز ، فالسحر شيء ضعيف له سبب خفي يتمكن أن يفعله أي واحد ولا يقترن بالتحدي ، بعكس المعجز في كل ذلك ( وَلا يُفْلِحُ السَّاحِرُونَ ) لا يظفرون بمرادهم تماما ، فإنه تمويه وتزييف للمستضعفين ، ولذا لم يوجد ساحر تمكّن من تكوين أمة وكانت له سيادة ورفعة.` },
            { text: "قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ", tafsir: `أي قال فرعون وملؤه لموسى عليه‌السلام : ( أَ جِئْتَنا لِتَلْفِتَنا ) على نحو الاستفهام الإنكاري ، أي : هل جئتنا يا موسى لتصرفنا ـ من « لفت » بمعنى صرف ـ ( عَمَّا وَجَدْنا عَلَيْهِ آباءَنا ) من عبادة الأصنام والملوك ، وترشدنا إلى عبادة الله ؟ إن هذا لا يكون ( وَتَكُونَ لَكُمَا الْكِبْرِياءُ فِي الْأَرْضِ وَما نَحْنُ لَكُما بِمُؤْمِنِينَ (78) وَقالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ ساحِرٍ عَلِيمٍ (79) فَلَمَّا جاءَ السَّحَرَةُ قالَ لَهُمْ مُوسى أَلْقُوا ما أَنْتُمْ مُلْقُونَ (80) فَلَمَّا أَلْقَوْا قالَ مُوسى ما جِئْتُمْ بِهِ السِّحْرُ الْكِبْرِياءُ ) السيادة والسلطة. فإنهم قالوا : إن موسى وهارون إنما ساقهم إلى هذه الدعوة إرادتهما أن يكونا سيدين ملكين على الناس ، فهما من طلاب العظمة والسلطة ( فِي الْأَرْضِ ) أرض مصر وما حولها ( وَما نَحْنُ لَكُما بِمُؤْمِنِينَ ) أي بمصدّقين في دعوى النبوة.` },
            { text: "وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَٰحِرٍ عَلِيمٍ", tafsir: `لملئه : ( ائْتُونِي بِكُلِّ ساحِرٍ عَلِيمٍ ) بالسحر ، بليغ في عمله ، لأواجه موسى به ، فإنه قد عجز عن دحض حجته ، فأراد الاستعانة بالسحرة ليقابل موسى بالمثل فتبطل حجته عليه‌السلام في زعمه. [81] فجمعوا له السحرة من كل مكان ولما ( جاءَ السَّحَرَةُ ) جمع « ساحر » نحو : كهنة ، وطلبة ، جمع « كاهن » و « طالب » . وجاء موسى عليه‌السلام في محضر فرعون والناس ( قالَ لَهُمْ مُوسى أَلْقُوا ما أَنْتُمْ مُلْقُونَ ) فإنهم كانوا يلقون حبالا وعصيّا من أيديهم على الأرض فيظهر للناس أنها حيّاة وأفاعي ، وقد أرادوا بذلك بيان أن عصيّ موسى عليه‌السلام أيضا من هذا القبيل ، وإذا بطلت هذه المعجزة تمكنوا من الخدش في سائر المعجزات التي أتى بها ، بأنها أيضا أقسام من السحر. و « ألقوا » ليس أمرا بالسحر ، بل بيانا لبطلانه.` },
            { text: "فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ", tafsir: `` },
            { text: "فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ", tafsir: `ألقت السحرة ما معها من الحبال والعصيّ ( قالَ مُوسى ) عليه‌السلام لهم : ( ما جِئْتُمْ بِهِ السِّحْرُ ) « ما » مبتدأ و « السحر » خبره ، إِنَّ اللهَ سَيُبْطِلُهُ إِنَّ اللهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ (81) وَيُحِقُّ اللهُ الْحَقَّ بِكَلِماتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ (82) يعني : إن الذي جئتم به هو السحر ، وليس السحر ما جئت به كما قلتم. ( إِنَّ اللهَ سَيُبْطِلُهُ ) يظهر بطلانه للناس ( إِنَّ اللهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ) فالله سبحانه لا يبقي على عمل يراد به إفساد الدين بطابع الإصلاح ، ولا يمضيه ، بل يبيّن بطلانه ويظهر زيفه.` },
            { text: "وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ", tafsir: `أي يظهر الله سبحانه الحق للناس ويحقّقه ، حتى يرون أنه حق وأن ما عداه باطل ( بِكَلِماتِهِ ) التكوينية وهي « كن فيكون » ( وَلَوْ كَرِهَ الْمُجْرِمُونَ ) أن يظهر الحق ويتبيّن زيف الباطل. وقد تحقّق ما قاله موسى عليه‌السلام فألقى عصاه ـ وقد صارت ثعبانا عظيما ـ فأكلت كل تلك الحبال والعصي ، وخرّ السحرة ساجدين ، وبطل كيد فرعون ، بل ظهر كون الحق مع موسى عليه‌السلام وأنه نبيّ مرسل. وهنا أمر لا بد من التنبيه عليه هو : أن القرآن إنما يأخذ موضع العبرة من القصة ، ولذا نجده في كل مناسبة يذكر طرفا خاصا منها. ففي مقام يذكر أول القصة ، وفي مقام وسطها أو آخرها ، وفي مقام يطرحها باختصار ، وفي مقام بتفصيل ، حسب اختلاف المقامات. فإذا كان الحديث حول عاقبة المجرمين ، ذكر غرق فرعون ، وإن كان حول غلبة رسل الله بالحجة ذكر غلبة موسى في إلقاء عصاه ، وإن كان حول العاقبة الحسنة للمؤمنين ذكر نجاة بني إسرائيل من مصر. وغالبا يخصّ الموضع المراد من القصة بجمل قصيرة من سائر مواضعها تحفظا على الربط والسياق. وقد أكثر سبحانه من القصص المرتبطة بالأمم الموحّدة الباقية ، فَما آمَنَ لِمُوسى إِلاَّ ذُرِّيَّةٌ مِنْ قَوْمِهِ عَلى خَوْفٍ مِنْ فِرْعَوْنَ وَمَلائِهِمْ أَنْ يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعالٍ فِي الْأَرْضِ وَإِنَّهُ لَمِنَ الْمُسْرِفِينَ (83) والأمم المشركة والملحدة الباقية ، لتكون لهم عبرة ، أما تفصيل قصص قوم لوط وشعيب وإلياس ـ مثلا ـ فليس من البلاغة ، أما قصة موسى وعيسى فلا بد من تفصيلهما لأنهما صاحبا شريعة يتمسك الناس بها إلى يوم الوقت المعلوم ، وهكذا بالنسبة إلى الاحتجاجات مع الملحدين والمشركين ، فقد بقي أكثر أهل العالم ملحدين مشركين طول الخط حتى يوم الناس هذا.` },
            { text: "فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ", tafsir: `ولم يصدّق دعوته وما جاء به ( إِلَّا ذُرِّيَّةٌ مِنْ قَوْمِهِ ) أي جماعة من الشباب ـ لا الكهول والكبراء ـ والضمير في « قومه » إما راجع إلى « فرعون » أي من قوم فرعون ، أو راجع إلى موسى عليه‌السلام أي : من بني إسرائيل ، فإنهم كانوا من أقرباء موسى عليه‌السلام لأن الجميع كانوا من أولاد يعقوب عليه‌السلام . وكان إيمانهم ( عَلى خَوْفٍ مِنْ فِرْعَوْنَ ) فقد كانوا يخافون بطشه ونكاله ، ( وَمَلَائِهِمْ ) أشرافهم وكبرائهم ، أن يؤذوهم و ( أَنْ يَفْتِنَهُمْ ) أي يعذبهم فرعون ويصرفهم عن دينهم ( وَإِنَّ فِرْعَوْنَ لَعالٍ ) قاهر متكبّر وسلطان ( فِي الْأَرْضِ ) فيقدر على ما يريد من التنكيل والعقاب ( وَإِنَّهُ لَمِنَ الْمُسْرِفِينَ ) الذين أسرفوا وتجاوزوا الحد في الطغيان ، فقد أسرف في القتل والظلم ، وادّعى الربوبية. والسر في هذا أن الأنبياء دائما يأتون إلى الناس عزّل بلا سلاح ومال ، والملوك الذين هم ضدّهم مزوّدون بالأمرين ، والناس بحاجة وَقالَ مُوسى يا قَوْمِ إِنْ كُنْتُمْ آمَنْتُمْ بِاللهِ فَعَلَيْهِ تَوَكَّلُوا إِنْ كُنْتُمْ مُسْلِمِينَ (84) فَقالُوا عَلَى اللهِ تَوَكَّلْنا رَبَّنا لا تَجْعَلْنا فِتْنَةً لِلْقَوْمِ الظَّالِمِينَ (85) إلى المال ، كما أنهم يخافون من القوة ، لذا تجبرهم الطبيعة على عدم الاعتناء بالأنبياء وإن كان الغالب أنهم يصدقونهم قلبا ، كما قال ذلك الشاعر للحسين عليه‌السلام : « قلوبهم معك وسيوفهم مع بني أمية » ، وقال تعالى : ( وَجَحَدُوا بِها وَاسْتَيْقَنَتْها أَنْفُسُهُمْ ) (1) . ومن ذلك نرى أن الملوك إذا قبلوا الدين دخل فيه أتباعهم. أما سر أن الأنبياء عزّل هو أن يكون في الدين صعوبة ليكون المؤمن مستحقا للأجر والثواب ، وهذا هو سر فضيلة السابقين إلى الدين ، لأنهم يلاقون من الصعوبة ما لا يلاقيه غيرهم.` },
            { text: "وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ", tafsir: `لقومه المؤمنين به : ( يا قَوْمِ إِنْ كُنْتُمْ آمَنْتُمْ بِاللهِ ) إيمانا صادقا راسخا ( فَعَلَيْهِ تَوَكَّلُوا ) فوّضوا أموركم إليه ( إِنْ كُنْتُمْ مُسْلِمِينَ ) أي إن كنتم منقادين لله ، فإن « الإسلام » هو الانقياد عملا ، كما قال تعالى : ( قالَتِ الْأَعْرابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلكِنْ قُولُوا أَسْلَمْنا ) (2) ، فالإيمان هو الاعتقاد ، والإسلام هو التسليم ، وبينهما عموم من وجه ، فكم من معتقد لا يسلم ، وكم من مسلم لا يعتقد.` },
            { text: "فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّٰلِمِينَ", tafsir: `أي قال قوم موسى : ( عَلَى اللهِ تَوَكَّلْنا ) فوّضنا أمورنا إليه واثقين بنصرته لنا ( رَبَّنا لا تَجْعَلْنا فِتْنَةً لِلْقَوْمِ الظَّالِمِينَ ) فنكون امتحانا ( 1) النمل : 15. ( 2) الحجرات : 15. وَنَجِّنا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكافِرِينَ (86) وَأَوْحَيْنا إِلى مُوسى وَأَخِيهِ أَنْ تَبَوَّءا لِقَوْمِكُما بِمِصْرَ بُيُوتاً وَاجْعَلُوا بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا الصَّلاةَ للكفار ، كما قال سبحانه : ( وَجَعَلْنا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً ) (1) . فإن الكفار يمتحنون ويفتنون بالمؤمنين ، ومعنى دعائهم : أن لا يسلّط الكفار عليهم ، حتى يبتلوا بهم ، ويكون الكفار ممتحنين بسبب هؤلاء. و قد روي عن الإمامين الباقر والصادق عليهما‌السلام أنهما فسرا الآية بأن معناها : لا تسلّطهم علينا فتفتنهم بنا (2) .` },
            { text: "وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَٰفِرِينَ", tafsir: `خلّصنا ( بِرَحْمَتِكَ ) بفضلك ( مِنَ الْقَوْمِ الْكافِرِينَ ) أي فرعون وملأه.` },
            { text: "وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَبَشِّرِ ٱلْمُؤْمِنِينَ", tafsir: `هارون ، لما قرب الأمر ، وأردنا نجاتهم من أيدي فرعون وقومه ( أَنْ تَبَوَّءا لِقَوْمِكُما بِمِصْرَ بُيُوتاً ) يقال : « تبوأ بيتا » أي اتخذ بيتا ، من باب « باء » بمعنى « رجع » ، فإن الإنسان يرجع إلى بيته كلما خرج ، ولذا يسمى البيت « مبوأ » . أي اجعلا لبني إسرائيل المؤمنين بكم في مدينة مصر بيوتا خاصة بهم ( وَاجْعَلُوا بُيُوتَكُمْ قِبْلَةً ) قال سعيد بن جبير إن معناه : اجعلوا بيوتكم يقابل بعضها بعضا ( وَأَقِيمُوا الصَّلاةَ ) أي أديموها وواظبوا على فعلها. ولعلّ هذين الأمرين باتخاذ البيوت بتلك الكيفية وإقامة الصلاة ، أن الأول لجمعهم في محل واحد بعضهم قبال بعض فلا يكونوا منتشرين هنا وهناك ، ( 1) الفرقان : 21. ( 2) بحار الأنوار : ج 5 ص 216. وَبَشِّرِ الْمُؤْمِنِينَ (87) وَقالَ مُوسى رَبَّنا إِنَّكَ آتَيْتَ فِرْعَوْنَ وَمَلَأَهُ زِينَةً وَأَمْوالاً فِي الْحَياةِ الدُّنْيا رَبَّنا لِيُضِلُّوا عَنْ سَبِيلِكَ وذلك التكتّل والتنظيم مهم جدا في جمع الأفراد بصبغة واحدة ، ولنشر الأخبار ، وتنفيذ الأوامر فيهم بسرعة. كما أن إقامة الصلاة وتوثيق الصلات بالله سبحانه تولد فيهم طاقة روحية ونشاطا ، وتزكّي نفوسهم استعدادا لمقاومة القوم وعدم تأثير دعايات الكفار فيهم. ومن المعلوم أن تزكية الروح لها أكبر الأثر في الانتصار والثبات ( وَبَشِّرِ ) يا موسى ( الْمُؤْمِنِينَ ) بالله ربك ، بأنه سوف يفرّج عنهم.` },
            { text: "وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ", tafsir: `مخاطبا لله سبحانه : ( رَبَّنا إِنَّكَ آتَيْتَ فِرْعَوْنَ وَمَلَأَهُ ) أي أعطيته والأشراف من قومه ( زِينَةً ) يتزيّنون بها من الملابس والمراكب والمساكن وغيرها ( وَأَمْوالاً ) يديرون بها شؤونهم ويتعاظمون بها على غيرهم ( فِي الْحَياةِ الدُّنْيا ) فإنها توجب الإغراء في هذه الحياة بالنسبة الى الغير ، كما توجب الكبرياء بالنسبة الى أصحابها. وكان ذكر هذه الجملة للتضرع إليه سبحانه ببيان كونهما صدا للدعوة هنا ـ في هذه الحياة ـ كما يقول الطالب شاكيا إلى مدير المدرسة : « إنك جعلت فلانا مراقبا في المدرسة ، وهو فاسد » يريد بيان الضراعة في أن كونه في المدرسة يسبب الفساد. ( رَبَّنا لِيُضِلُّوا عَنْ سَبِيلِكَ ) « اللام » للعاقبة ، كما قال سبحانه : ( فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَناً ) (1) ، أي أن عاقبة إعطائك ( 1) القصص : 9. رَبَّنَا اطْمِسْ عَلى أَمْوالِهِمْ وَاشْدُدْ عَلى قُلُوبِهِمْ فَلا يُؤْمِنُوا حَتَّى يَرَوُا الْعَذابَ الْأَلِيمَ (88) المال لهم إضلال الناس عن دينك وطريقك وشريعتك ( رَبَّنَا اطْمِسْ عَلى أَمْوالِهِمْ ) « الطمس » محو الأثر ، وهنا بمعنى « الضرب » ولذا عدّى ب « على » أي اضرب عليها وامحي أثرها ، حتى لا تكون سدا في طريق الدعوة. وهل كان دعاؤه عليه‌السلام بمسخها كما ذكر جمع من المفسرين ، أو ذهاب البركة وإفنائها تدريجيا ؟ احتمالان. ( وَاشْدُدْ عَلى قُلُوبِهِمْ ) أبلغ بهم إلى غاية الشدة والقسوة التي يستحق بها العقاب ، لانقطاع كل رجاء في إيمانهم ، فإن الكافر لا يهلكه الله سبحانه إلا إذا انقطع كل رجاء ـ حسب الظاهر ـ عن قبول الحق ، فكان هذا دعاء لسرعة إهلاكهم ، بذكر السبب. ومن هذا القبيل دعاء الإمام أمير المؤمنين عليه‌السلام لزيادة شقوة ابن ملجم ، فإنه دعاء بالخلاص من القوم بذكر السبب ، وحيث أن الأمر كائن لا محالة ، فالدعاء بتقديمه ليس خلافا لموازين الدعاء إذا كان فيه فائدة مهمة. ( فَلا يُؤْمِنُوا حَتَّى يَرَوُا الْعَذابَ الْأَلِيمَ ) المؤلم الموجع ، أي أنهم يلازمون عدم الإيمان إلى رؤية العذاب ، وفي ذلك الوقت لا ينفع الإيمان لأنه إيمان إلجاء لا إيمان عقيدة. ومن المعلوم أن استحقاق العقاب والثواب إنما هو بالعمل المنبعث عن العقيدة. وربما يحتمل أن المراد ب « اشدد » اتركها حتى تتشدد وتتصلب ولا تلطف بها ألطافك الخفية ، فيكون كقوله ( مَنْ يُضْلِلِ اللهُ قالَ قَدْ أُجِيبَتْ دَعْوَتُكُما فَاسْتَقِيما وَلا تَتَّبِعانِّ سَبِيلَ الَّذِينَ لا يَعْلَمُونَ (89) وَجاوَزْنا بِبَنِي إِسْرائِيلَ الْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ بَغْياً وَعَدْواً حَتَّى إِذا أَدْرَكَهُ فَما لَهُ مِنْ هادٍ ) (1) ، المراد به تركهم حتى يضلوا.` },
            { text: "قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ", tafsir: `الله سبحانه في جواب دعاء موسى وهارون عليهما‌السلام : ( قَدْ أُجِيبَتْ دَعْوَتُكُما ) في طمس أموال فرعون وقومه والتشديد على قلوبهم ( فَاسْتَقِيما ) في الإرشاد والتبليغ والدعوة إلى الله سبحانه. روي عن الصادق عليه‌السلام : « أنه كان بين قول الله عزوجل : ( قَدْ أُجِيبَتْ دَعْوَتُكُما ) وبين أخذ فرعون ، أربعين سنة » (2) . ( وَلا تَتَّبِعانِّ سَبِيلَ الَّذِينَ لا يَعْلَمُونَ ) في الضجر من طول المدة ، وعدم الوثوق والاطمئنان بوعد الله سبحانه ، فإن لله في أحكامه مصالح لا يتضجّر منها إلا الجاهل ولا يستبطئ وعوده إلا المستعجل. [91] وجاء الموعد وخرج بنو إسرائيل بقيادة موسى عليه‌السلام ووصلوا إلى البحر وانفلق الماء عن طريق لهم وجاء فرعون بجنوده ليدركهم ويأخذهم وينكّل بهم ، وتوسط قوم موسى البحر حتى دخل قوم فرعون ولما أن خرج موسى وقومه توسط البحر فرعون وقومه وإذا بالماء ينطبق عليهم ويغرقون جميعا ( وَجاوَزْنا بِبَنِي إِسْرائِيلَ الْبَحْرَ ) عبرنا بهم البحر حتى جاوزوه سالمين ( فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ ) أي مع جنوده ( بَغْياً وَعَدْواً ) إنما اتّبعوهم ليبغوا عليهم ( حَتَّى إِذا أَدْرَكَهُ ) أدرك فرعون ( 1) الزمر : 24. ( 2) تفسير العياشي : ج 2 ص 127. الْغَرَقُ قالَ آمَنْتُ أَنَّهُ لا إِلهَ إِلاَّ الَّذِي آمَنَتْ بِهِ بَنُوا إِسْرائِيلَ وَأَنَا مِنَ الْمُسْلِمِينَ (90) آلْآنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنْتَ مِنَ الْمُفْسِدِينَ (91) ( الْغَرَقُ ) أي وصل إليه الماء ليغرقه ( قالَ ) فرعون للتخلص من الغرق : ( آمَنْتُ أَنَّهُ لا إِلهَ إِلَّا ) الإله ( الَّذِي آمَنَتْ بِهِ بَنُوا إِسْرائِيلَ ) يعني الله سبحانه ، فقد كان إلى ذلك الحين ينكره ويدعي الربوبية ( وَأَنَا مِنَ الْمُسْلِمِينَ ) إني أسلم له. لكن إيمانه كان للتخلص والنجاة ، بالإضافة إلى أن الإيمان لا ينفع إذا عاين الإنسان الموت كما قال سبحانه : ( وَلَيْسَتِ التَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ السَّيِّئاتِ حَتَّى إِذا حَضَرَ أَحَدَهُمُ الْمَوْتُ قالَ إِنِّي تُبْتُ الْآنَ ) (1) . [92] ولما كان هذا الكلام قال له جبرائيل : ( آلْآنَ ) تؤمن على نحو الإنكار ، فإن هذا الإيمان عن إلجاء واضطرار ( وَقَدْ عَصَيْتَ قَبْلُ ) ذلك بترك الإيمان وفعل المعاصي والفساد في الأرض ( وَكُنْتَ مِنَ الْمُفْسِدِينَ ) في الأرض بظلم الناس والتعدي عليهم وإطفاء نور الأنبياء إلى غير ذلك. روي عن الصادق عليه‌السلام قال : « ما أتى جبرائيل رسول الله إلا كئيبا حزينا ، ولم يزل كذلك منذ أهلك الله فرعون ، فلما أمره الله بإنزال هذه الآية ( وَقَدْ عَصَيْتَ قَبْلُ وَكُنْتَ مِنَ الْمُفْسِدِينَ ) ، نزل عليه وهو ضاحك مستبشر ، فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : ما أتيتني يا جبرائيل إلا وتبيّنت الحزن من وجهك حتى الساعة. قال : نعم يا محمد ! لما أغرق ( 1) النساء : 19. فَالْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ آيَةً الله فرعون قال : « آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل وأنا من المسلمين » فأخذت حمأة فوضعتها في فيه ، ثم قلت له : « ءآلآن وقد عصيت قبل وكنت من المفسدين » وعملت ذاك من غير أمر الله عزوجل ، ثم خفت أن تلحقه الرحمة من الله عزوجل ويعذبني الله على ما فعلت. فلما كان الآن وأمرني الله عزوجل أن أودي إليك ما قلته أنا لفرعون ، أمنت وعلمت أن ذلك كان لله تعالى رضى » (1) .` },
            { text: "وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ", tafsir: `` },
            { text: "ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ", tafsir: `` },
            { text: "فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةً وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ عَنْ ءَايَٰتِنَا لَغَٰفِلُونَ", tafsir: `إن الناس غالبا لا يصدقون بموت العظماء ، فكيف بمن ادّعى الربوبية وكان الناس يعبدونه. ولذا لما أخبر موسى عليه‌السلام أن فرعون أغرق ، لم يصدقه الناس ، ولذا اقتضت حكمة الله سبحانه أن ينجي فرعون ببدنه ، بأن ألقى بدنه الذي لا روح فيه على الساحل حتى رآه الناس. ولذا قال سبحانه « اليوم » أي يوم غرقك ننجيك يا فرعون ببدنك فقط ، فلم يذهب مع الماء ليضيع جسمه ، ولا أكلته الأسماك ( لِتَكُونَ لِمَنْ خَلْفَكَ ) من الناس ( آيَةً ) علامة على قدرة الله سبحانه ، وأنه لم يكن فرعون إلها ، فإن الإله لا يموت ولا يغرق. والخطاب إما حقيقي بأن خوطب به فرعون وهو حي ، أو موجه إلى الناس يراد به إعلامهم بمصير كل ظالم ، فالخطاب من قبيل خطابات العقلاء لما لا يعقل ، كقول الشاعر : أيا شجر الخابور ما لك مورقا كأنك لم تجزع على ابن طريف وقوله : ( 1) بحار الأنوار : ج 13 ص 117. وَإِنَّ كَثِيراً مِنَ النَّاسِ عَنْ آياتِنا لَغافِلُونَ (92) وَلَقَدْ بَوَّأْنا بَنِي إِسْرائِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْناهُمْ مِنَ الطَّيِّباتِ فَمَا اخْتَلَفُوا حَتَّى جاءَهُمُ الْعِلْمُ إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيامَةِ فِيما كانُوا فِيهِ أيا جبلي نعمان بالله خليا نسيم الصبا يخلص إليّ نسيمها ( وَإِنَّ كَثِيراً مِنَ النَّاسِ عَنْ آياتِنا لَغافِلُونَ ) غافلون عن التفكير في أدلتنا ودلائلنا.` },
            { text: "وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ", tafsir: `مكّنا ( بَنِي إِسْرائِيلَ ) بعد نجاتهم من فرعون وقومه ، وخروجهم من مصر ( مُبَوَّأَ صِدْقٍ ) مكان ثبات وأمن ، فإن المكان المتزلزل الذي لا يستقر فيه الإنسان هو مبوأ كذب ، إذ لا وجه له واقع ، فهو يحكي عما لا يكون ، إذ ظاهره الاستقرار وباطنه الانفلات والانقلاب. فقد مكّنهم سبحانه من الشام وبيت المقدس ( وَرَزَقْناهُمْ مِنَ الطَّيِّباتِ ) بعد ما كانوا في أرض مصر متزلزلي المنزل حيث يضطهدهم فرعون ، ولم يكن لديهم ما يأكلون حتى صفرت أيديهم من المال ، لكن لم يبقوا على تلك الحالة ، فإنهم لما طال عليهم الأمد اختلفوا ، ولم يكن اختلافهم عن جهل فإنهم ما ( اخْتَلَفُوا حَتَّى جاءَهُمُ الْعِلْمُ ) وعرفوا كل شيء ، بل اختلفوا حسدا واستعلاء ، كما هو شأن كل أمة ، أنهم يتّحدون ما داموا قلة مضطهدين ، فإذا كثروا وأمنوا وأثروا اختلفوا على المال والجاه وما أشبههما. ( إِنَّ رَبَّكَ ) يا رسول الله ( يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيامَةِ ) فقد أحيلوا إلى المحكمة الكبرى حيث لم يرضخوا لأحكام الله في الدنيا ولا ترافعوا إلى أنبيائه ليبيّنوا لهم الحق من الباطل ( فِيما كانُوا فِيهِ يَخْتَلِفُونَ (93) فَإِنْ كُنْتَ فِي شَكٍّ مِمَّا أَنْزَلْنا إِلَيْكَ فَسْئَلِ الَّذِينَ يَقْرَؤُنَ الْكِتابَ مِنْ قَبْلِكَ لَقَدْ جاءَكَ يَخْتَلِفُونَ ) من الأصول والفروع. وقد روي أنهم انقسموا إلى إحدى وسبعين فرقة. [95] وبعد تمام قصة موسى عليه‌السلام وفرعون ، يتوجه الخطاب إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم ليعرف الذين يشكّون ، أنهم في شكّهم على غير حق بعد إقامة الحجة ، وكثيرا ما يوجه الخطاب إلى أحد ما ، ليعرف غيره قصد المتكلم على نحو « إياك أعني واسمعي يا جارة » . ومن المحتمل أن يكون الخطاب لكل من يلتفت إلى هذه القصة ، كما ذكر علماء البلاغة أن الخطاب في قوله تعالى : ( وَلَوْ تَرى إِذِ الْمُجْرِمُونَ ناكِسُوا رُؤُسِهِمْ ) (1) ، متوجه إلى كل من يأتي منه الرؤية. ( فَإِنْ كُنْتَ ) يا رسول الله ، أو إن كنت أيها السامع. وهذا لا ينافي قوله ( مِمَّا أَنْزَلْنا إِلَيْكَ ) إذ يستعمل ذلك بالنسبة إلى كل من أمر بتبليغه ، كما قال سبحانه : ( أَنْزَلَ اللهُ إِلَيْكُمْ ذِكْراً ) (2) ، و ( أَنْزَلْنا إِلَيْكُمْ كِتاباً فِيهِ ذِكْرُكُمْ ) (3) ، باعتبار أن الغاية من الإنزال هم. ( فِي شَكٍّ مِمَّا أَنْزَلْنا إِلَيْكَ ) من العقائد الحقة والقصص السالفة ( فَسْئَلِ الَّذِينَ يَقْرَؤُنَ الْكِتابَ مِنْ قَبْلِكَ ) فإنهم في واقع أمرهم يعترفون بكل ذلك وإن أنكره بعضهم عنادا وحسدا ، فإن الكتب السالفة كانت تدل على كل تلكم الأصول وحقائق هذه القصص ( لَقَدْ جاءَكَ ( 1) السجدة : 13. ( 2) الطلاق : 11. ( 3) الأنبياء : 11. الْحَقُّ مِنْ رَبِّكَ فَلا تَكُونَنَّ مِنَ المُمْتَرِينَ (94) وَلا تَكُونَنَّ مِنَ الَّذِينَ كَذَّبُوا بِآياتِ اللهِ فَتَكُونَ مِنَ الْخاسِرِينَ (95) الْحَقُّ مِنْ رَبِّكَ ) يا رسول الله ، أو أيها السامع ، فإن القرآن وما يشتمل عليه من الأصول والأحكام والقصص كله حق لا مرية فيه ( فَلا تَكُونَنَّ مِنَ المُمْتَرِينَ ) « الامتراء » طلب الشك مع ظهور الدليل ، وهو من « مرى الضرع » إذا مسحه ليدر ، ولا معنى لمسحه بعد درّه الحليب. ولا يخفى أن مثل هذا الكلام ، إنما يفيد التلقين والإيماء ، فإن المطلب إذا ألقي على النفس قبلته. فلا يقال : ما فائدة هذا الكلام ؟ إذ المخاطب إن كان شاكا لا يزول شكه بقولك : « لا تشك » ، وإن لم يكن شاكا كان مثل هذا الكلام معه لغوا ، كما أنه لا تنافي بين ( فَإِنْ كُنْتَ فِي شَكٍّ ) وبين ( فَلا تَكُونَنَّ مِنَ المُمْتَرِينَ ) فإنها بمعنى : « إن كنت في شك فاسأل حتى يزول الشك ولا تبقى فيه إلى الأبد » .` },
            { text: "فَإِن كُنتَ فِى شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَٰبَ مِن قَبْلِكَ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ", tafsir: `` },
            { text: "وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَٰسِرِينَ", tafsir: `أي لا تكن في جملة المكذبين بأدلة الله وحججه التي أقامها على توحيده وسائر صفاته وأحكامه ( فَتَكُونَ مِنَ الْخاسِرِينَ ) الذين خسروا أنفسهم وأموالهم وأهليهم إذ هم صرفوها واشتروا بذلك العذاب والنكال. [97] وبعد وضوح الحجة وظهور المحجة وقيام الأدلة على ما أنزل على الرسول فما هو سبب إصرار قوم على الكفر والتكذيب ؟ إنهم حقت فيهم كلمة الله ، فقد بيّن سبحانه سابقا أن من أعرض عن الحق بعد وضوحه لا بد وأن يقسو قلبه حتى أنه لو رأى كل آية لا يؤمن ، فقد إِنَّ الَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لا يُؤْمِنُونَ (96) وَلَوْ جاءَتْهُمْ كُلُّ آيَةٍ حَتَّى يَرَوُا الْعَذابَ الْأَلِيمَ (97) فَلَوْ لا كانَتْ قَرْيَةٌ آمَنَتْ فَنَفَعَها إِيمانُها إِلاَّ قَوْمَ يُونُسَ لَمَّا آمَنُوا كَشَفْنا عَنْهُمْ عَذابَ الْخِزْيِ فِي الْحَياةِ الدُّنْيا أغلق قلبه وطبع عليه فلا يؤمن وإن رأى الحجج والآيات ( إِنَّ الَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ ) أي ثبتت ( لا يُؤْمِنُونَ ) بالله وما جاء به الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ", tafsir: `خارقة تدل على صدق الأنبياء في الدعوة إلى التوحيد وسائر الأمور الدينية ( حَتَّى يَرَوُا الْعَذابَ الْأَلِيمَ ) المؤلم الموجع ، فهناك يتيقّنون بأنهم كانوا على ضلالة لكن إيمانهم حينذاك لا ينفعهم. [99] إن سنة الله لا بد وأن تجري بالنسبة إلى المكذبين بإهلاكهم ، وقد تقرّر أنهم لا يؤمنون حتى يروا العذاب الأليم ، فهل هناك من خلاص من هذا العذاب والهلاك ؟ هنا يذكر سبحانه أن الخلاص ممكن وهو أن يسلك المكذبون ـ حتى ولو شاهدوا العذاب ـ مسلك المؤمنين فيؤمنوا ويرجعوا عن غيّهم ( فَلَوْ لا كانَتْ قَرْيَةٌ آمَنَتْ فَنَفَعَها إِيمانُها ) أي لماذا لم يؤمن أهل القرى التي أهلكناها ، حين شاهدوا العذاب ؟ وفي « لو لا » معنى التأنيب نحو : « هلّا امتنعت عن النساء وقد دعيت إلى التعفف عنهن » ( إِلَّا قَوْمَ يُونُسَ ) استثناء متصل فإن قوم يونس خارجون عن هذا التأنيب ( لَمَّا آمَنُوا ) بعد مشاهدة العذاب ( كَشَفْنا عَنْهُمْ عَذابَ الْخِزْيِ ) أي رفعنا عنهم العذاب الموجب لخزيهم ( فِي الْحَياةِ الدُّنْيا ) وَمَتَّعْناهُمْ إِلى حِينٍ (98) وَلَوْ شاءَ رَبُّكَ لَآمَنَ مَنْ فِي الْأَرْضِ كُلُّهُمْ جَمِيعاً أي في هذه الحياة القريبة فصرفنا عنهم العذاب ( وَمَتَّعْناهُمْ ) أبقيناهم متنعمين بنعم الدنيا ( إِلى حِينٍ ) جاء أجلهم فماتوا بالآجال المكتوبة. فقد ورد أنه ما رد الله العذاب إلا عن قوم يونس عليه‌السلام فكان يدعوهم إلى الإسلام فأبوا ذلك ، فهمّ أن يدعو عليهم ، وكان فيهم رجلان عالم وعابد وكان اسم العالم « روبيل » واسم العابد « تنوخا » وكان العابد يشير على يونس بالدعاء عليهم وكان العالم ينهاه ويقول : لا تدع فإن الله يستجيب لك ولا يحب هلاك عباده. فقبل يونس عليه‌السلام قول العابد ولم يقبل قول العالم حين يئس منهم بعد ما دعاهم ثلاثا وثلاثون سنة. فدعا عليهم ، فأوحى الله إليه يخبره بأنه يأتيهم العذاب في سنة كذا في شهر كذا في يوم كذا ، فلما قرب الوقت خرج يونس من بينهم مع العابد وبقي العالم فيهم. فلما كان في ذلك اليوم نزل العذاب ـ بأن رأوا في اليوم الموعود ريح صفراء مظلمة مسرعة لها صرير وحفيف ـ فقال العالم لهم : يا قوم أفزعوا إلى الله فلعله يرحمكم فيرد العذاب عنكم. فقالوا : كيف نصنع ؟ فقال : اخرجوا إلى المغارة وفرقوا بين النساء والأولاد ، وبين الإبل وأولادها ، وبين البقر وأولادها ، وبين الغنم وأولادها ، ثم ابكوا. و فعلوا ذلك وضجّوا وبكوا ، ف رحمهم‌الله ، وصرف عنهم العذاب ، وفرق العذاب على الجبال وقد نزل وقرب منهم (1) .` },
            { text: "فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ", tafsir: `` },
            { text: "وَلَوْ شَآءَ رَبُّكَ لَـَٔامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ", tafsir: `يا رسول الله ( لَآمَنَ مَنْ فِي الْأَرْضِ ) من البشر ( كُلُّهُمْ جَمِيعاً ) بلا استثناء أحد. ولذا جيء بتأكيدين ، حتى لا يظن ( 1) تفسير القمي : ج 1 ص 317. أَفَأَنْتَ تُكْرِهُ النَّاسَ حَتَّى يَكُونُوا مُؤْمِنِينَ (99) وَما كانَ لِنَفْسٍ أَنْ تُؤْمِنَ أن التأكيد الأول عرفي لا حقيقي ، فإنه سبحانه قادر على أن يلجئ الناس إلى الإيمان ، كما أنه قادر على أن يحف الإيمان بالمغريات التي ترغّب الناس في الإيمان تلقائيا بلا جبر ، لكنه لم يشأ الأمرين ، إذ تعدم فائدة الإيمان حينئذ لعدم حصول الاختبار بالإكراه والإغراء ( أَ فَأَنْتَ ) يا رسول الله ( تُكْرِهُ النَّاسَ حَتَّى يَكُونُوا مُؤْمِنِينَ ) أي لا ينبغي لك إكراه الناس على الإيمان ، أو لا تقدر على ذلك ، فإن الإيمان أمر قلبي لا يدخل تحت طوقك. فإن قيل : فلما ذا يكره الإسلام الناس على ترك المنكرات وفعل الواجبات ؟ قلنا : إن ذلك بالنسبة إلى من قبل الدين كمن قبل القانون الذي يجبر على تطبيقه عليه ، أما من لم يقبل وهو مورد الآية فلا إكراه له. فإن قيل : فكيف لا يقبل الإسلام من الكفار غير الكتابيين إلا الإسلام أو القتال ؟ قلنا : إن ذلك إذا خرقوا العهود التي بينهم وبين المسلمين ، وذلك غير الإكراه الابتدائي. [101] إن الله سبحانه لم يكره الناس على الإيمان ، ولكنه بيّن لهم الطريق ، فإن أحدا لا يتمكن من الإيمان إلا بإذنه سبحانه ، بأن يهديه الطريق ، أما من هداه وأرشده ثم أعرض عنه وسلك طريقا آخر فالله سبحانه يجعل عليه الرجس الروحي ، إذ تنغلق منافذ عقله ، وتتردى نفسه في مهاوي الضلالة التي هي أبشع أنواع الرجس ( وَما كانَ لِنَفْسٍ أَنْ تُؤْمِنَ إِلاَّ بِإِذْنِ اللهِ وَيَجْعَلُ الرِّجْسَ عَلَى الَّذِينَ لا يَعْقِلُونَ (100) قُلِ انْظُرُوا ما ذا فِي السَّماواتِ وَالْأَرْضِ إِلَّا بِإِذْنِ اللهِ ) بأن يمكنها من الإيمان ويدعوها إليه ويرشدها إلى طريقه ( وَيَجْعَلُ ) الله ( الرِّجْسَ ) الدنس الروحي الذي هو أسوأ أقسام الدنس ، فإن القذارات الظاهرية تذهب بالغسل ونحوه ، أما القذارة الروحية فلا تذهب بألف غسل وغسل ( عَلَى الَّذِينَ لا يَعْقِلُونَ ) أي لا يعملون عقولهم للاستضاءة والاستنارة.` },
            { text: "وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ", tafsir: `` },
            { text: "قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا تُغْنِى ٱلْـَٔايَٰتُ وَٱلنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( انْظُرُوا ما ذا فِي السَّماواتِ وَالْأَرْضِ ) من الآيات الدالة على توحيد الله سبحانه وصفاته ، فإن في كل شيء آية. قال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : « إنما العلم ثلاثة : آية محكمة ، أو فريضة عادلة ، أو سنة قائمة ، وما خلاهن فهو فضل » (1) . فالآية المحكمة : هي الآيات الكونية الدالة بإحكامها وإتقانها على التوحيد وسائر صفاته سبحانه من العلم والقدرة والحياة والإرادة ، وأنه لا يفعل العبث .. وغيرها. والفريضة العادلة : هي الأخلاق التي هي فرائض بأن يسير البشر في عدلها ووسطها ، فلا جبن ولا تهوّر بل شجاعة ، ولا بخل ولا سرف بل جود ، ولا شره ولا تزهد بل عفة .. . وهكذا. والسنة القائمة : هي الأحكام الإسلامية التي هي سنن الحياة السعيدة ومناهجها القائمة إلى الأبد ، لا تزول ولا تتغير. ( 1) عوالي اللآلي : ج 4 ص 79. وَما تُغْنِي الْآياتُ وَالنُّذُرُ عَنْ قَوْمٍ لا يُؤْمِنُونَ (101) فَهَلْ يَنْتَظِرُونَ إِلاَّ مِثْلَ أَيَّامِ الَّذِينَ خَلَوْا مِنْ قَبْلِهِمْ قُلْ فَانْتَظِرُوا إِنِّي مَعَكُمْ مِنَ الْمُنْتَظِرِينَ (102) ثُمَّ نُنَجِّي رُسُلَنا وَالَّذِينَ آمَنُوا كَذلِكَ حَقًّا عَلَيْنا نُنْجِ الْمُؤْمِنِينَ (103) ( وَما تُغْنِي الْآياتُ وَالنُّذُرُ ) أي لا تفيد هذه الدلالات والبراهين الجلية ، ولا يفيد الإنذار والوعظ ( عَنْ قَوْمٍ لا يُؤْمِنُونَ ) إذ أنهم أغلقوا قلوبهم وغمضوا أبصارهم. وإنما عدي ب « عن » لأنه أشرب معنى « الدفع » ، أي لا تدفع الآيات والعضلات العذاب عن قوم لا يؤمنون ، فقد كان السياق حول عذاب المكذبين وأنه سبحانه يجعل الرجس عليهم.` },
            { text: "فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ", tafsir: `أي ينتظر هؤلاء الكفار الذين لا تفيدهم الآيات والنذر ، والاستفهام إنكاري ( إِلَّا مِثْلَ أَيَّامِ الَّذِينَ خَلَوْا مِنْ قَبْلِهِمْ ) أي إلا العذاب والهلاك ، والمراد بأيامهم : وقائعهم المؤلمة ، ومعنى « خلوا » مضوا. والحاصل أنهم إن لم يؤمنوا فلينتظروا العذاب كما نزل بقوم عاد وثمود وغيرهم ( قُلْ ) يا رسول الله لهؤلاء الكفار : ( فَانْتَظِرُوا ) مثل تلك الأيام بعد ما أعرضتم عن الإيمان ( إِنِّي مَعَكُمْ مِنَ الْمُنْتَظِرِينَ ) فلننتظر جميعا حتى يأتيكم العذاب.` },
            { text: "ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ", tafsir: `عند نزول العذاب ( نُنَجِّي رُسُلَنا ) فلا يصيبهم مكروه ( وَالَّذِينَ آمَنُوا ) من بين أولئك الكفار ، فلا يحرق الرطب مع اليابس ـ كما اشتهر على ألسنة الناس ـ ( كَذلِكَ ) أي كما ننجي الرسل ( حَقًّا عَلَيْنا نُنْجِ الْمُؤْمِنِينَ ) أي نجاة المؤمنين لازم علينا في الحكمة. قُلْ يا أَيُّهَا النَّاسُ إِنْ كُنْتُمْ فِي شَكٍّ مِنْ دِينِي فَلا أَعْبُدُ الَّذِينَ تَعْبُدُونَ مِنْ دُونِ اللهِ وَلكِنْ أَعْبُدُ اللهَ الَّذِي يَتَوَفَّاكُمْ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُؤْمِنِينَ (104) وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفاً ويحتمل أن يكون « كذلك » للمؤخر ـ لا المقدم ـ أي نجاة المؤمنين الآن كنجاة المؤمنين سابقا.` },
            { text: "قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ", tafsir: `يا رسول الله : ( يا أَيُّهَا النَّاسُ ) خطاب للناس بصورة عامة ( إِنْ كُنْتُمْ فِي شَكٍّ مِنْ دِينِي ) وطريقتي التي جئت بها ، أ حق هي أم باطل ؟ فلا تدرون ذلك ، فإن شككم لا يزحزحني من عقيدتي ودعوتي ، بل أبقى صامدا للدعوة ( فَلا أَعْبُدُ الَّذِينَ تَعْبُدُونَ مِنْ دُونِ اللهِ ) ولا يثنيني إلى عبادة تلك الآلهة كثرة عبّادها وشككم في ديني ، كما هو الغالب في الأفراد الذين يدعون إلى طريقة فلا يجدون مؤيدين لها فيعدلون عنها ( وَلكِنْ أَعْبُدُ اللهَ الَّذِي يَتَوَفَّاكُمْ ) فهو الذي يميتكم وتكون ناصيتكم في قبضته ومصيركم إليه. وهذا تهديد لهم ، وتذكير بأن الموت بيد الله سبحانه وليس للأصنام شيء ( وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُؤْمِنِينَ ) بالله وكتبه ورسله وشرائعه. [106] وكأن المقام صار مقام مخاطبة الله لنبيه ، وأن الشاكين حاضرين في محضر الرسول حين يتلقى الوحي ، من باب الإلفات الذي هو نوع من البلاغة ، ولذا قال : ( وَأَنْ أَقِمْ ) يا رسول الله ( وَجْهَكَ ) واتجاهك فإن « الوجه » لمّا كان المحل الذي يتوجه الناس به إلى غيرهم ، أمر بإقامته ، وعدم صرفه إلى هنا وهناك ( لِلدِّينِ ) أي طريقة الإسلام ( حَنِيفاً ) أي في حال كونك مائلا عن سائر الأديان ، أو مستقيما في وَلا تَكُونَنَّ مِنَ الْمُشْرِكِينَ (105) وَلا تَدْعُ مِنْ دُونِ اللهِ ما لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذاً مِنَ الظَّالِمِينَ (106) وَإِنْ يَمْسَسْكَ اللهُ بِضُرٍّ فَلا كاشِفَ لَهُ إِلاَّ هُوَ طريقتك ودعوتك ( وَلا تَكُونَنَّ مِنَ الْمُشْرِكِينَ ) الذين يشركون بالله غيره ، وكأن عطف « أن أقم » على تقدير : « قيل لي » أن أقم.` },
            { text: "وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ", tafsir: `` },
            { text: "وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ ٱلظَّٰلِمِينَ", tafsir: `يا رسول الله ( مِنْ دُونِ اللهِ ) أي غير الله سبحانه ( ما لا يَنْفَعُكَ ) إن أطعته ( وَلا يَضُرُّكَ ) ضرر معتد به إن عصيته. وإنما قيدنا بذلك لأنه المفهوم ، فإن الله سبحانه هو المستقل بالنفع والضرر أما غيره من الآلهة المزعومة فمنها ما لا ينفع ولا يضر إطلاقا ، كالأصنام ، ومنها ما لا ينفع ولا يضر إلا بإذن الله سبحانه ، كفرعون ونمرود وغيرهما من الأصنام البشرية ( فَإِنْ فَعَلْتَ ) تلك العبادة والدعوة لغير الله ( فَإِنَّكَ إِذاً ) في ذلك الحين ( مِنَ الظَّالِمِينَ ) الذين ظلموا أنفسهم بإيجاب العذاب عليها وعلى سائر الناس فيما لو صاروا سببا للضلال والغواية. ولا ينافي كون الخطاب متوجها إلى النبي مع مقام عصمته ، لأنه تعليمي ، بالإضافة إلى إمكان استحالة المقدم في الشرط ، وإنما صدق الجملة بصدق الملازمة. [108] الأصنام والآلهة المزعومة لا تنفع ولا تضر ، أما الله سبحانه فهو وحده المالك للنفع والضرر ولكل شيء ، فمن اللازم أن يدعوه الإنسان وحده ( وَإِنْ يَمْسَسْكَ ) يا رسول الله ( اللهُ بِضُرٍّ ) أي إن أحلّ ضرا. وكأن الإتيان بلفظ « المس » لإفادة أن أقل مقدار من الضر الذي يمس الإنسان مسا ، لا كاشف له سوى الله ، فكيف بالمقدار الكبير منه ؟ ( فَلا كاشِفَ لَهُ ) لا دافع له ( إِلَّا هُوَ ) إلا الله وحده ، فهو القادر وَإِنْ يُرِدْكَ بِخَيْرٍ فَلا رَادَّ لِفَضْلِهِ يُصِيبُ بِهِ مَنْ يَشاءُ مِنْ عِبادِهِ وَهُوَ الْغَفُورُ الرَّحِيمُ (107) قُلْ يا أَيُّهَا النَّاسُ قَدْ جاءَكُمُ الْحَقُّ مِنْ رَبِّكُمْ فَمَنِ اهْتَدى فَإِنَّما يَهْتَدِي على دفع الضر ( وَإِنْ يُرِدْكَ ) من « أراد يريد » ( بِخَيْرٍ ) يقال : « يريدك بالخير » و « يريد بك الخير » بمعنى واحد ( فَلا رَادَّ لِفَضْلِهِ ) أي لا يقدر أحد على منعه. قال بعض المفسرين : إن ذكر الإرادة مع الخير ، والمس مع الضر ، لتلازم بين الأمرين ، للتنبيه على أن الخير مراد بالذات ، وأن الضر إنما يمسّ البشر لا بالقصد الأول ، ووضع الفضل موضع الضمير للدلالة على أنه متفضل بما يريد بهم من الخير لا استحقاقا لهم عليه ، ولم يستثني لأن مراد الله لا يمكن رده (1) . ( يُصِيبُ بِهِ ) أي بالخير ( مَنْ يَشاءُ مِنْ عِبادِهِ ) فيعطيه كما تقتضي حكمته البالغة ( وَهُوَ الْغَفُورُ ) لذنوبهم ( الرَّحِيمُ ) بهم يرحمهم ويتفضل عليهم. [109] وأخيرا جاء الحق إلى الناس ، والرسول مأمور بالتبليغ ، وبعد ذلك كل امرئ وما اختار ( قُلْ ) يا رسول الله للناس : ( يا أَيُّهَا النَّاسُ ) على نحو العموم ( قَدْ جاءَكُمُ الْحَقُ ) هو دين الإسلام المشتمل على كل شيء مما يحتاجه الإنسان في مختلف مجالات الحياة ( مِنْ رَبِّكُمْ ) إلهكم الحقيقي ومربّيكم ( فَمَنِ اهْتَدى ) إلى الحق ( فَإِنَّما يَهْتَدِي ( 1) بحار الأنوار : ج 68 ص 110. لِنَفْسِهِ وَمَنْ ضَلَّ فَإِنَّما يَضِلُّ عَلَيْها وَما أَنَا عَلَيْكُمْ بِوَكِيلٍ (108) وَاتَّبِعْ ما يُوحى إِلَيْكَ وَاصْبِرْ حَتَّى يَحْكُمَ اللهُ وَهُوَ خَيْرُ الْحاكِمِينَ (109) لِنَفْسِهِ ) فإن فائدة هدايته عائدة إليه ( وَمَنْ ضَلَ ) عنه وعدل إلى سائر السبل ( فَإِنَّما يَضِلُّ عَلَيْها ) أي على نفسه ، فإن ضرر الضلال يعود إلى الإنسان نفسه ( وَما أَنَا عَلَيْكُمْ بِوَكِيلٍ ) فلست أنا مسئولا عمن ضل بعد إراءته الطريق وإرشاده السبيل ، فأنتم موكلون إلى أنفسكم وليس عليّ إلا البلاغ.` },
            { text: "وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهِۦ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ", tafsir: `` },
            { text: "قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍ", tafsir: `` },
            { text: "وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ", tafsir: `` }
        ]
    }
});
